import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        // Create a 2D array to store the position and speed of each car
        int[][] cars = new int[position.length][2];

        // Populate the 2D array with the given data
        for (int i = 0; i < position.length; i++) {
            cars[i][0] = position[i];
            cars[i][1] = speed[i];
        }

        // Sort the cars based on their positions in descending order
        Arrays.sort(cars, new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                return Integer.compare(b[0], a[0]);
            }
        });

        // Initialize variables to keep track of the number of fleets and the time it takes for the current fleet to reach the destination
        int numFleets = 0;
        double currentTime = -1.0;

        // Iterate over each car in descending order of their positions
        for (int[] car : cars) {
            // Calculate the time it takes for the current car to reach the destination
            double timeToDestination = (double) (target - car[0]) / car[1];

            // If the current car reaches the destination after the current fleet, start a new fleet
            if (timeToDestination > currentTime) {
                numFleets++;
                currentTime = timeToDestination;
            }
        }

        return numFleets;
    }
}

