import java.util.Arrays;

public class Solution {
    public int[] shortestToChar(String s, char c) {
        int n = s.length();
        int[] res = new int[n];

        // First pass: from left to right
        int lastSeenIndex = -1; // Keep track of the last seen index of 'c'
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == c) {
                res[i] = 0;
                lastSeenIndex = i; // Update the last seen index
            } else {
                if (lastSeenIndex != -1) { // If 'c' has been seen before
                    res[i] = i - lastSeenIndex; // Calculate distance to the last seen 'c'
                } else {
                    res[i] = Integer.MAX_VALUE; // If no 'c' has been seen yet, mark as unknown
                }
            }
        }

        // Second pass: from right to left
        lastSeenIndex = -1; // Reset for the second pass
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == c) {
                res[i] = 0;
                lastSeenIndex = i; // Update the last seen index
            } else {
                if (lastSeenIndex != -1) { // If 'c' has been seen before in this pass
                    int distFromRight = lastSeenIndex - i; // Calculate distance to the next seen 'c'
                    res[i] = Math.min(res[i], distFromRight); // Update with the minimum distance
                }
            }
        }

        return res;
    }
}

