// #Medium #Array #Simulation #2022_03_28_Time_16_ms_(93.75%)_Space_50.9_MB_(75.89%)
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        Set<String> obstacleSet = new HashSet<>();
        for (int[] obstacle : obstacles) {
            obstacleSet.add(obstacle[0] + "," + obstacle[1]);
        }

        int x = 0;
        int y = 0;
        // direction: 0=right, 1=up, 2=left, 3=down
        int[][] directions = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
        int currentDirectionIndex = 1; // start facing up (north)
        int maxDistanceSquared = 0;

        for (int command : commands) {
            if (command == -2) { // turn left
                currentDirectionIndex = (currentDirectionIndex + 3) % 4;
            } else if (command == -1) { // turn right
                currentDirectionIndex = (currentDirectionIndex + 1) % 4;
            } else { // move forward
                for (int i = 0; i < command; i++) {
                    int newX = x + directions[currentDirectionIndex][0];
                    int newY = y + directions[currentDirectionIndex][1];

                    if (!obstacleSet.contains(newX + "," + newY)) {
                        x = newX;
                        y = newY;
                    } else {
                        break; // stop moving forward when encountering an obstacle
                    }
                }
            }

            maxDistanceSquared = Math.max(maxDistanceSquared, x * x + y * y);
        }

        return maxDistanceSquared;
    }
}

