// #Easy #Array #Hash_Table #Sorting #Binary_Search
// #2022_03_28_Time_18_ms_(68.20%)_Space_72.2_MB_(19.02%)
import java.util.HashSet;

public class Solution {
    public int[] fairCandySwap(int[] aliceSizes, int[] bobSizes) {
        int sumAlice = 0;
        for (int size : aliceSizes) {
            sumAlice += size;
        }

        int sumBob = 0;
        HashSet<Integer> setBob = new HashSet<>();
        for (int size : bobSizes) {
            sumBob += size;
            setBob.add(size);
        }

        int diff = (sumBob - sumAlice) / 2;
        for (int aliceSize : aliceSizes) {
            if (setBob.contains(aliceSize + diff)) {
                return new int[] {aliceSize, aliceSize + diff};
            }
        }
        throw new RuntimeException("No solution found");
    }
}

