// #Medium #Dynamic_Programming #Math #Probability_and_Statistics
// #2022_03_23_Time_1_ms_(96.04%)_Space_41.7_MB_(78.22%)
public class Solution {
    public double soupServings(int n) {
        if (n >= 4800) return 1;
        n = (n + 24) / 25;
        Map<String, Double> memo = new HashMap<>();
        return dfs(n, n, memo);
    }

    private double dfs(int a, int b, Map<String, Double> memo) {
        if (a <= 0 && b > 0) return 1.0;
        if (b <= 0 && a > 0) return 0.0;
        if (a <= 0 && b <= 0) return 0.5;
        String key = a + "," + b;
        if (memo.containsKey(key)) return memo.get(key);
        double res = 0.25 * dfs(a - 4, b, memo)
                + 0.25 * dfs(a - 3, b - 1, memo)
                + 0.25 * dfs(a - 2, b - 2, memo)
                + 0.25 * dfs(a - 1, b - 3, memo);
        memo.put(key, res);
        return res;
    }
}

