// #Easy #String #Hash_Table #2022_03_28_Time_1_ms_(100.00%)_Space_40.8_MB_(89.40%)
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public String[] uncommonFromSentences(String s1, String s2) {
        Map<String, Integer> countMap = new HashMap<>();

        // Split the sentences into words and update their counts in the map
        for (String word : s1.split(" ")) {
            countMap.put(word, countMap.getOrDefault(word, 0) + 1);
        }
        for (String word : s2.split(" ")) {
            countMap.put(word, countMap.getOrDefault(word, 0) + 1);
        }

        // Create a list to store the uncommon words
        List<String> result = new ArrayList<>();

        // Iterate over the map and add words with a count of 1 to the result list
        for (String word : countMap.keySet()) {
            if (countMap.get(word) == 1) {
                result.add(word);
            }
        }

        // Convert the list to an array and return it
        String[] uncommonWords = new String[result.size()];
        return result.toArray(uncommonWords);
    }
}

