// #Medium #Array #String #Hash_Table #2022_03_28_Time_1_ms_(97.13%)_Space_42.3_MB_(86.23%)
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;

public class Solution {
    public List<String> findAndReplacePattern(String[] words, String pattern) {
        List<String> result = new ArrayList<>();

        for (String word : words) {
            if (match(word, pattern)) {
                result.add(word);
            }
        }

        return result;
    }

    private boolean match(String word, String pattern) {
        HashMap<Character, Character> mapping = new HashMap<>();
        HashMap<Character, Character> reverseMapping = new HashMap<>();

        for (int i = 0; i < word.length(); i++) {
            char c1 = word.charAt(i);
            char c2 = pattern.charAt(i);

            if ((mapping.containsKey(c1) && mapping.get(c1) != c2) || 
                (reverseMapping.containsKey(c2) && reverseMapping.get(c2) != c1)) {
                return false;
            }

            mapping.put(c1, c2);
            reverseMapping.put(c2, c1);
        }

        return true;
    }
}

