public class Solution {
    public String maskPII(String s) {
        // Check if the string is an email address or a phone number
        if (s.contains("@")) {
            return maskEmail(s);
        } else {
            return maskPhoneNumber(s);
        }
    }

    private String maskEmail(String s) {
        // Split the email into local part and domain
        String[] parts = s.split("@");
        String localPart = parts[0];
        String domain = parts[1];

        // Convert to lowercase
        localPart = localPart.toLowerCase();
        domain = domain.toLowerCase();

        // Mask the middle letters of the local part
        StringBuilder maskedLocalPart = new StringBuilder();
        maskedLocalPart.append(localPart.charAt(0));
        for (int i = 0; i < 5; i++) {
            maskedLocalPart.append("*");
        }
        if (localPart.length() > 1) {
            maskedLocalPart.append(localPart.charAt(localPart.length() - 1));
        }

        // Return the masked email
        return maskedLocalPart.toString() + "@" + domain;
    }

    private String maskPhoneNumber(String s) {
        // Remove all separation characters
        StringBuilder digits = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                digits.append(c);
            }
        }

        // Determine the country code length
        int countryCodeLength = digits.length() - 10;

        // Mask the phone number
        StringBuilder maskedPhoneNumber = new StringBuilder();
        if (countryCodeLength == 0) {
            maskedPhoneNumber.append("***-***-");
        } else if (countryCodeLength == 1) {
            maskedPhoneNumber.append("+*-");
        } else if (countryCodeLength == 2) {
            maskedPhoneNumber.append("+**-");
        } else if (countryCodeLength == 3) {
            maskedPhoneNumber.append("+***-");
        }

        // Append the last 4 digits of the local number
        String localNumber = digits.substring(Math.max(0, digits.length() - 10));
        maskedPhoneNumber.append(localNumber.substring(localNumber.length() - 4));

        return maskedPhoneNumber.toString();
    }
}

