public class Solution {
    public double new21Game(int n, int k, int maxPts) {
        if (k == 0 || n >= k + maxPts) return 1.0;

        double[] dp = new double[n + 1];
        dp[0] = 1.0;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= Math.min(i, maxPts); j++) {
                if (i - j < k) {
                    dp[i] += dp[i - j] / maxPts;
                }
            }
        }

        double sum = 0.0;
        for (int i = k; i <= n; i++) {
            sum += dp[i];
        }

        return sum;
    }
}

