    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        s = s.substring(1, s.length() - 1);

        for (int i = 1; i < s.length(); i++) {
            String left = s.substring(0, i);
            String right = s.substring(i);

            List<String> leftList = restore(left);
            List<String> rightList = restore(right);

            for (String l : leftList) {
                for (String r : rightList) {
                    result.add("(" + l + ", " + r + ")");
                }
            }
        }

        return result;
    }

    private List<String> restore(String s) {
        List<String> result = new ArrayList<>();

        if (s.equals("0")) {
            result.add(s);
        } else if (!s.startsWith("0") || s.length() == 1) {
            // Add as integer
            result.add(s);

            for (int i = 1; i < s.length(); i++) {
                String left = s.substring(0, i);
                String right = s.substring(i);

                if (!right.endsWith("0")) {
                    result.add(left + "." + right);
                }
            }
        } else {
            // Starts with '0' and has more than one character
            if (s.length() > 1 && !s.substring(1).equals("0") && !s.substring(1).endsWith("0")) {
                result.add("0." + s.substring(1));
            }
        }

        return result;
    }
}

