public class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        int[][] result = new int[rows * cols][2];
        int index = 0;

        // directions: right, down, left, up
        int[] dx = {1, 0, -1, 0};
        int[] dy = {0, 1, 0, -1};

        int direction = 0; // start with moving right

        int stepsInCurrentDirection = 1;
        int stepsTakenInCurrentDirection = 0;
        int turnsTaken = 0;

        int x = cStart;
        int y = rStart;

        while (index < rows * cols) {
            if (x >= 0 && x < cols && y >= 0 && y < rows) {
                result[index][0] = y;
                result[index][1] = x;
                index++;
            }

            // move to the next cell
            x += dx[direction];
            y += dy[direction];
            stepsTakenInCurrentDirection++;

            if (stepsTakenInCurrentDirection == stepsInCurrentDirection) {
                turnsTaken++;
                direction = (direction + 1) % 4; // turn right

                // increase the number of steps in the next two directions
                if (turnsTaken % 2 == 0) {
                    stepsInCurrentDirection++;
                }

                stepsTakenInCurrentDirection = 0;
            }
        }

        return result;
    }
}

