// #Medium #String #Dynamic_Programming #Two_Pointers
// #2022_03_24_Time_21_ms_(73.78%)_Space_54.4_MB_(50.10%)
public class Solution {
    public String pushDominoes(String dominoes) {
        char[] res = new char[dominoes.length()];

        int n = dominoes.length();
        int[] forces = new int[n];

        // Calculate the force from the left
        int f = 0;
        for (int i = 0; i < n; i++) {
            if (dominoes.charAt(i) == 'R') {
                f = n;
            } else if (dominoes.charAt(i) == 'L') {
                f = 0;
            } else {
                f = Math.max(f - 1, 0);
            }
            forces[i] += f;
        }

        // Calculate the force from the right
        f = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (dominoes.charAt(i) == 'L') {
                f = n;
            } else if (dominoes.charAt(i) == 'R') {
                f = 0;
            } else {
                f = Math.max(f - 1, 0);
            }
            forces[i] -= f;
        }

        // Determine the final state based on the net force
        for (int i = 0; i < n; i++) {
            if (forces[i] > 0) {
                res[i] = 'R';
            } else if (forces[i] < 0) {
                res[i] = 'L';
            } else {
                res[i] = '.';
            }
        }

        return new String(res);
    }
}

