// #Hard #Array #Matrix #Union_Find #2022_03_23_Time_12_ms_(94.92%)_Space_118.5_MB_(65.25%)
public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int[] result = new int[hits.length];

        // Apply all the hits first
        for (int i = 0; i < hits.length; i++) {
            if (grid[hits[i][0]][hits[i][1]] == 1) {
                grid[hits[i][0]][hits[i][1]] = -1;
            }
        }

        // Mark the bricks that are connected to the top
        for (int j = 0; j < n; j++) {
            if (grid[0][j] == 1) {
                dfs(grid, 0, j);
            }
        }

        int index = hits.length - 1;
        // Revert each hit and count the number of bricks that will fall
        for (int i = hits.length - 1; i >= 0; i--) {
            if (grid[hits[i][0]][hits[i][1]] == -1) {
                grid[hits[i][0]][hits[i][1]] = 1;
                result[index--] = countFallenBricks(grid, hits[i][0], hits[i][1]);
            } else {
                result[index--] = 0;
            }
        }

        return result;
    }

    private void dfs(int[][] grid, int x, int y) {
        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[x][y] != 1) {
            return;
        }
        grid[x][y] = 2; // Mark as visited
        dfs(grid, x - 1, y);
        dfs(grid, x + 1, y);
        dfs(grid, x, y - 1);
        dfs(grid, x, y + 1);
    }

    private boolean isStable(int[][] grid, int x, int y) {
        if (x == 0) return true; // If it's at the top, it's stable

        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                int nx = x + i;
                int ny = y + j;
                if ((Math.abs(i) + Math.abs(j)) == 1 && nx >= 0 && nx < grid.length && ny >= 0 && ny < grid[0].length) {
                    if (grid[nx][ny] == 2 || isStable(grid, nx, ny)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private int countFallenBricks(int[][] grid, int x, int y) {
        // Perform DFS from the top to mark all stable bricks
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[0][j] == 1) {
                dfs(grid, 0, j);
            }
        }

        int count = 0;
        boolean[][] visited = new boolean[grid.length][grid[0].length];

        // Check if the brick at the reverted hit location is connected to any stable brick
        if (isStable(grid, x, y)) {
            return 0; // If it's stable, no bricks will fall
        }

        countBricks(grid, x, y, visited, count);

        // Reset the grid to its original state after counting fallen bricks
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == 2) {
                    grid[i][j] = 1;
                }
            }
        }

        return count;

    }

    private int countBricks(int[][] grid, int x, int y, boolean[][] visited, int count) {
        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || visited[x][y] || grid[x][y] != 1) {
            return count;
        }

        visited[x][y] = true;

        // If the brick is not stable, count it as a fallen brick
        if (!isStable(grid, x, y)) {
            count++;
            grid[x][y] = 2; // Mark as counted

            // Recursively count other bricks that are connected to this one but not to any stable brick
            count = countBricks(grid, x - 1, y, visited, count);
            count = countBricks(grid, x + 1, y, visited, count);
            count = countBricks(grid, x, y - 1, visited, count);
            count = countBricks(grid, x, y + 1, visited, count);
        }
        return count;
    }
}

