// #Medium #Array #Dynamic_Programming #Math #Game_Theory
// #2022_03_28_Time_0_ms_(100.00%)_Space_41.7_MB_(79.95%)
public class Solution {
    public boolean stoneGame(int[] piles) {
        int n = piles.length;
        // Create a 2D array to store the maximum stones Alice can get
        int[][] dp = new int[n][n];

        // Initialize the diagonal of the 2D array with the number of stones in each pile
        for (int i = 0; i < n; i++) {
            dp[i][i] = piles[i];
        }

        // Fill up the rest of the 2D array using dynamic programming
        for (int d = 1; d < n; d++) {
            for (int i = 0; i + d < n; i++) {
                int j = i + d;
                dp[i][j] = Math.max(piles[i] - dp[i + 1][j], piles[j] - dp[i][j - 1]);
            }
        }

        // If the maximum stones Alice can get is greater than 0, she wins
        return dp[0][n - 1] > 0;
    }
}

