// #2022_03_27_Time_0_ms_(100.00%)_Space_42.4_MB_(41.93%)

public class Solution {
    private int maxDepth;
    private TreeNode result;

    public TreeNode subtreeWithAllDeepest(TreeNode root) {
        maxDepth = -1;
        dfs(root, 0);
        return result;
    }

    private int dfs(TreeNode node, int depth) {
        if (node == null) {
            return depth - 1;
        }
        if (depth > maxDepth) {
            maxDepth = depth;
            result = node;
        } else if (depth == maxDepth) {
            // No need to create a new TreeNode here
            // We can simply update the result with the current node
            result = node;
        }

        int leftMax = dfs(node.left, depth + 1);
        int rightMax = dfs(node.right, depth + 1);

        if (leftMax == maxDepth && rightMax == maxDepth) {
            return maxDepth;
        } else if (leftMax == maxDepth) {
            return leftMax;
        } else if (rightMax == maxDepth) {
            return rightMax;
        }
        return Math.max(leftMax, rightMax);
    }

    public static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        public TreeNode(int x) { val = x; }
    }
}

