public class Solution {
    public int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        // Create a 2D array to store the job information
        int[][] jobs = new int[difficulty.length][2];

        // Populate the jobs array with difficulty and profit information
        for (int i = 0; i < difficulty.length; i++) {
            jobs[i][0] = difficulty[i];
            jobs[i][1] = profit[i];
        }

        // Sort the jobs array based on difficulty
        Arrays.sort(jobs, Comparator.comparingInt(a -> a[0]));

        // Initialize variables to store the maximum profit and total profit
        int maxProfit = 0;
        int totalProfit = 0;

        // Iterate over each worker's ability
        for (int w : worker) {
            // Initialize the best job index for the current worker
            int bestJobIndex = -1;

            // Iterate over each job to find the best job for the current worker
            for (int i = 0; i < jobs.length; i++) {
                if (jobs[i][0] <= w) {
                    // Update the best job index if a better job is found
                    if (bestJobIndex == -1 || jobs[i][1] > jobs[bestJobIndex][1]) {
                        bestJobIndex = i;
                    }
                } else {
                    // Break the loop as we have sorted the jobs by difficulty
                    break;
                }
            }

            // Update the total profit if a job is assigned to the current worker
            if (bestJobIndex != -1) {
                totalProfit += jobs[bestJobIndex][1];
            }
        }

        return totalProfit;
    }
}

