// #Hard #String #Breadth_First_Search #2022_03_27_Time_2_ms_(99.58%)_Space_42.6_MB_(97.17%)
public class Solution {
    public int kSimilarity(String a, String b) {
        Queue<String> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();

        queue.offer(a);
        visited.add(a);

        int step = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String current = queue.poll();

                if (current.equals(b)) return step;

                for (String next : getNext(current, b)) {
                    if (!visited.contains(next)) {
                        visited.add(next);
                        queue.offer(next);
                    }
                }
            }

            step++;
        }

        throw new RuntimeException("No solution found");
    }

    private List<String> getNext(String s, String target) {
        List<String> result = new ArrayList<>();

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != target.charAt(i)) {
                for (int j = i + 1; j < s.length(); j++) {
                    if (s.charAt(j) == target.charAt(i)) {
                        char[] chars = s.toCharArray();
                        swap(chars, i, j);
                        result.add(new String(chars));
                    }
                }

                break;
            }
        }

        return result;
    }

    private void swap(char[] chars, int i, int j) {
        char temp = chars[i];
        chars[i] = chars[j];
        chars[j] = temp;
    }
}

