public class Solution {
    /**
     * Returns the middle node of a singly linked list.
     * If there are two middle nodes, returns the second middle node.
     *
     * @param head The head of the singly linked list
     * @return The middle node of the linked list
     */
    public ListNode middleNode(ListNode head) {
        // Initialize two pointers, slow and fast.
        ListNode slow = head;
        ListNode fast = head;

        // Move the fast pointer twice as fast as the slow pointer.
        while (fast != null && fast.next != null) {
            slow = slow.next;  // Move the slow pointer one step at a time.
            fast = fast.next.next;  // Move the fast pointer two steps at a time.
        }

        // When the fast pointer reaches the end of the list, the slow pointer will be at the middle node.
        return slow;
    }
}

