public class Solution {
    public int minSwap(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int[][] dp = new int[n][2];

        // Initialize base case for no swap and swap at the first position
        dp[0][0] = 0; // No swap
        dp[0][1] = 1; // Swap

        for (int i = 1; i < n; i++) {
            dp[i][0] = Integer.MAX_VALUE;
            dp[i][1] = Integer.MAX_VALUE;

            if (nums1[i - 1] < nums1[i] && nums2[i - 1] < nums2[i]) {
                // If both arrays are increasing without swap, update dp values
                dp[i][0] = Math.min(dp[i][0], dp[i - 1][0]);
                dp[i][1] = Math.min(dp[i][1], dp[i - 1][1]);
            }

            if (nums1[i - 1] < nums2[i] && nums2[i - 1] < nums1[i]) {
                // If swap makes both arrays increasing, update dp values
                dp[i][0] = Math.min(dp[i][0], dp[i - 1][1]);
                dp[i][1] = Math.min(dp[i][1], dp[i - 1][0] + 1);
            }
        }

        return Math.min(dp[n - 1][0], dp[n - 1][1]);
    }
}

