// #2022_03_24_Time_4_ms_(97.00%)_Space_43.2_MB_(41.20%)
public class Solution {
    public int rectangleArea(int[][] rectangles) {
        final int MOD = (int) 1e9 + 7;
        List<int[]> events = new ArrayList<>();

        for (int[] rect : rectangles) {
            // Add start event
            events.add(new int[]{rect[1], rect[0], rect[2], 1});
            // Add end event
            events.add(new int[]{rect[3], rect[0], rect[2], -1});
        }

        // Sort events by y-coordinate and then by type (start or end)
        Collections.sort(events, (a, b) -> a[0] == b[0] ? a[3] - b[3] : a[0] - b[0]);

        TreeSet<Integer> active = new TreeSet<>();
        int area = 0;
        int prevY = 0;

        for (int[] event : events) {
            if (event[3] == 1) {
                // Add start x-coordinate to the active set
                active.add(event[1]);
                // Add end x-coordinate to the active set
                active.add(event[2]);
            } else {
                // Remove start x-coordinate from the active set
                active.remove(event[1]);
                // Remove end x-coordinate from the active set
                active.remove(event[2]);
            }

            int width = 0;
            Integer prevX = null;
            for (Integer x : active) {
                if (prevX != null) {
                    width += x - prevX;
                }
                prevX = x;
            }

            // Calculate the area and update it
            area = (int)((long) area + (long) width * Math.max(0L, event[0] - prevY)) % MOD;
            prevY = event[0];
        }

        return area;
    }
}

