import java.util.*;

public class Solution {
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        // Build the adjacency list
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int[] res = new int[n];

        for (int i = 0; i < n; i++) {
            boolean[] visited = new boolean[n];
            dfsDistance(graph, i, -1, 0, visited, res);
        }

        return res;
    }

    private void dfsDistance(List<List<Integer>> graph, int node, int parent, int distance, boolean[] visited, int[] res) {
        visited[node] = true;

        for (int child : graph.get(node)) {
            if (!visited[child]) {
                dfsDistance(graph, child, node, distance + 1, visited, res);
            }
        }

        // Accumulate the distances
        for (int i = 0; i < graph.size(); i++) {
            if (!visited[i] && i != node) {
                dfsDistanceHelper(graph, i, -1, 0, new boolean[graph.size()], res, node);
            }
        }
    }

    private void dfsDistanceHelper(List<List<Integer>> graph, int node, int parent, int distance, boolean[] visited, int[] res, int targetNode) {
        if (node == targetNode) {
            return;
        }

        visited[node] = true;

        for (int child : graph.get(node)) {
            if (!visited[child]) {
                dfsDistanceHelper(graph, child, node, distance + 1, visited, res, targetNode);
            }
        }

        // Accumulate the distances
        if (node != targetNode) {
            res[targetNode] += distance;
        }
    }
}

