public class Solution {
    public boolean buddyStrings(String s, String goal) {
        if (s.length() != goal.length()) return false;

        int count = 0;
        char[] chars1 = new char[2];
        char[] chars2 = new char[2];

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != goal.charAt(i)) {
                if (count == 2) return false;
                chars1[count] = s.charAt(i);
                chars2[count] = goal.charAt(i);
                count++;
            }
        }

        return count == 2 && chars1[0] == chars2[1] && chars1[1] == chars2[0] 
               || (count == 0 && hasDuplicate(s));
    }

    private boolean hasDuplicate(String s) {
