public class Solution {
    public int[] advantageCount(int[] nums1, int[] nums2) {
        // Create a priority queue to store the indices of nums2
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> b[0] - a[0]);

        // Store the index and value of each element in nums2 into the priority queue
        for (int i = 0; i < nums2.length; i++) {
            pq.offer(new int[] {nums2[i], i});
        }

        // Sort nums1 in ascending order
        Arrays.sort(nums1);

        // Initialize two pointers, one at the start and one at the end of nums1
        int left = 0;
        int right = nums1.length - 1;

        // Initialize an array to store the result
        int[] res = new int[nums1.length];

        // Iterate through the priority queue
        while (!pq.isEmpty()) {
            int[] curr = pq.poll();

            // If the current element in nums1 is greater than the current element in nums2,
            // assign it to the corresponding index in the result array and move the right pointer
            if (nums1[right] > curr[0]) {
                res[curr[1]] = nums1[right];
                right--;
            } 
            // Otherwise, assign the smallest element in nums1 to the corresponding index in the result array
            // and move the left pointer
            else {
                res[curr[1]] = nums1[left];
                left++;
            }
        }

        return res;
    }
}

