public class Solution {
    public String shiftingLetters(String s, int[][] shifts) {
        char[] chars = s.toCharArray();
        for (int[] shift : shifts) {
            int start = shift[0];
            int end = shift[1];
            int direction = shift[2];

            if (direction == 1) {
                // Shift forward
                for (int i = start; i <= end; i++) {
                    chars[i] = (char) ((chars[i] - 'a' + 1) % 26 + 'a');
                }
