// #Medium #Array #Dynamic_Programming #Matrix #2022_06_16_Time_6_ms_(99.18%)_Space_65_MB_(98.71%)
public class Solution {
    public int minPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length;
        int n = grid[0].length;

        // Initialize dp array with the values of the first row
        int[] dp = new int[n];
        for (int j = 0; j < n; j++) {
            dp[j] = grid[0][j];
        }

        // Iterate over each row starting from the second row
        for (int i = 1; i < m; i++) {
            int[] temp = new int[n];

            // For each cell in the current row, calculate the minimum cost to reach it
            for (int j = 0; j < n; j++) {
                int minCost = Integer.MAX_VALUE;

                // Try moving from all cells in the previous row to the current cell
                for (int k = 0; k < n; k++) {
                    int cost = dp[k] + moveCost[grid[i - 1][k]][j];
                    minCost = Math.min(minCost, cost);
                }

                // Update the minimum cost to reach the current cell
                temp[j] = grid[i][j] + minCost;
            }

            // Update dp array for the next row
            dp = temp;
        }

        // The minimum cost of a path is the minimum value in the last row of dp array
        int minCost = Integer.MAX_VALUE;
        for (int j = 0; j < n; j++) {
            minCost = Math.min(minCost, dp[j]);
        }

        return minCost;
    }
}

