public class Solution {
    public long countBadPairs(int[] nums) {
        HashMap<Integer, Integer> freqMap = new HashMap<>();
        long badPairCount = 0;

        for (int i = 0; i < nums.length; i++) {
            int diff = nums[i] - i;

            // If the difference is already in the map, it means we have found a good pair
            if (freqMap.containsKey(diff)) {
                badPairCount += i - freqMap.get(diff);
            } else {
                // If not, then all previous pairs are bad pairs
                badPairCount += i;
            }

            // Update the frequency of the difference in the map
            freqMap.put(diff, freqMap.getOrDefault(diff, 0) + 1);
        }

        return badPairCount;
    }
}

