public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private Integer[][][] memo;

    public int distinctSequences(int n) {
        memo = new Integer[7][n + 1][n + 1];
        return dfs(0, -1, new int[7], n);
    }

    private int dfs(int prev, int lastEqualIndex, int[] lastSeen, int rollsLeft) {
        if (rollsLeft == 0) return 1;
        if (memo[prev + 1][lastEqualIndex + 1][rollsLeft] != null) return memo[prev + 1][lastEqualIndex + 1][rollsLeft];

        int res = 0;
        for (int i = 1; i <= 6; i++) {
            if ((prev == -1 || gcd(prev, i) == 1) && 
                (lastSeen[i] == -1 || rollsLeft - lastSeen[i] > 2)) {
                int[] newLastSeen = lastSeen.clone();
                newLastSeen[i] = n - rollsLeft;
                res += dfs(i, lastEqualIndex, newLastSeen, rollsLeft - 1);
                res %= MOD;
            }
        }

        memo[prev + 1][lastEqualIndex + 1][rollsLeft] = res;
        return res;
    }

    private int gcd(int a, int b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }
}

