// #2022_06_26_Time_32_ms_(100.00%)_Space_108.9_MB_(100.00%)
import java.util.*;

public class Solution {
    public long countPairs(int n, int[][] edges) {
        // Create an adjacency list to represent the graph
        List<List<Integer>> adjList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adjList.add(new ArrayList<>());
        }

        // Populate the adjacency list with the given edges
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adjList.get(u).add(v);
            adjList.get(v).add(u);  // Since it's an undirected graph, add both directions
        }

        // Initialize a visited array to keep track of visited nodes during DFS
        boolean[] visited = new boolean[n];

        // Initialize the count of unreachable pairs and the size of each connected component
        long unreachablePairs = 0;
        int[] componentSizes = new int[n];
        int componentIndex = 0;

        // Perform DFS to find all connected components in the graph
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                componentSizes[componentIndex] = dfs(adjList, visited, i);
                componentIndex++;
            }
        }

        // Calculate the number of unreachable pairs based on the sizes of connected components
        long totalNodes = n;
        for (int i = 0; i < componentIndex; i++) {
            long nodesInComponent = componentSizes[i];
            long nodesOutsideComponent = totalNodes - nodesInComponent;
            unreachablePairs += nodesInComponent * nodesOutsideComponent;
        }

        return unreachablePairs / 2;  // Divide by 2 to avoid counting each pair twice
    }

    private int dfs(List<List<Integer>> adjList, boolean[] visited, int node) {
        if (visited[node]) {
            return 0;
        }

        visited[node] = true;
        int size = 1;

        for (int neighbor : adjList.get(node)) {
            size += dfs(adjList, visited, neighbor);
        }

        return size;
    }
}

