// #Medium #Depth_First_Search #Graph #2022_08_14_Time_18_ms_(89.33%)_Space_112.3_MB_(69.17%)
public class Solution {
    public int closestMeetingNode(int[] edges, int node1, int node2) {
        Set<Integer> visited1 = new HashSet<>();
        Set<Integer> visited2 = new HashSet<>();

        dfs(edges, node1, visited1);
        dfs(edges, node2, visited2);

        int minDistance = Integer.MAX_VALUE;
        int result = -1;

        for (int i = 0; i < edges.length; i++) {
            if (visited1.contains(i) && visited2.contains(i)) {
                int distance1 = getDistance(edges, node1, i);
                int distance2 = getDistance(edges, node2, i);

                int maxDistance = Math.max(distance1, distance2);

                if (maxDistance < minDistance || (maxDistance == minDistance && (result == -1 || i < result))) {
                    minDistance = maxDistance;
                    result = i;
                }
            }
        }

        return result;
    }

    private void dfs(int[] edges, int node, Set<Integer> visited) {
        if (node == -1 || visited.contains(node)) {
            return;
        }

        visited.add(node);
        dfs(edges, edges[node], visited);
    }

    private int getDistance(int[] edges, int start, int target) {
        int distance = 0;
        int current = start;

        while (current != -1 && current != target) {
            current = edges[current];
            distance++;
        }

        return current == target ? distance : Integer.MAX_VALUE;
    }
}

