public class Solution {
    public int shortestSequence(int[] rolls, int k) {
        Set<Integer> set = new HashSet<>();
        for (int roll : rolls) {
            set.add(roll);
        }

        if (set.size() < k) {
            return k - set.size() + 1;
        }

        boolean[] seen = new boolean[k];
        int count = 0;

        for (int i = 0; i < rolls.length; i++) {
            if (rolls[i] <= k && !seen[rolls[i] - 1]) {
                seen[rolls[i] - 1] = true;
                count++;
                if (count == k) {
                    count = 0;
                    for (int j = 0; j < k; j++) {
                        seen[j] = false;
                    }
                }
            }
        }

        int result = 1;
        while (result <= rolls.length + 1) {
            boolean found = true;
            for (int start = 0; start <= rolls.length - result; start++) {
                boolean validSequence = true;
                boolean[] tempSeen = new boolean[k];
                int tempCount = 0;

                for (int i = start; i < start + result; i++) {
                    if (rolls[i] <= k && !tempSeen[rolls[i] - 1]) {
                        tempSeen[rolls[i] - 1] = true;
                        tempCount++;
                        if (tempCount == k) {
                            tempCount = 0;
                            for (int j = 0; j < k; j++) {
                                tempSeen[j] = false;
                            }
                        }
                    }
                }

                if (tempCount != 0 || !validSequence) {
                    validSequence = false;
                } else {
                    validSequence = true;
                }

                if (!validSequence) {
                    found = false;
                    break;
                }
            }
            if (!found) {
                return result;
            }
            result++;
        }

        // If no sequence is not found within the length of rolls array
        return result - 1;
    }
}

