public class Solution {
    public boolean canChange(String start, String target) {
        int n = start.length();

        // Check if the number of 'L' and 'R' in both strings are equal
        int countLStart = 0;
        int countRStart = 0;
        int countLTarget = 0;
        int countRTarget = 0;

        for (int i = 0; i < n; i++) {
            if (start.charAt(i) == 'L') {
                countLStart++;
            } else if (start.charAt(i) == 'R') {
                countRStart++;
            }

            if (target.charAt(i) == 'L') {
                countLTarget++;
            } else if (target.charAt(i) == 'R') {
                countRTarget++;
            }
        }

        // If the counts are not equal, it's impossible to transform start into target
        if (countLStart != countLTarget || countRStart != countRTarget) {
            return false;
        }

        int i = 0, j = 0;

        while (i < n && j < n) {
            // Skip all '_' in both strings
            while (i < n && start.charAt(i) == '_') {
                i++;
            }

            while (j < n && target.charAt(j) == '_') {
                j++;
            }

            // If we have reached the end of either string, break the loop
            if (i >= n || j >= n) {
                break;
            }

            // Check if the current characters in both strings are equal
            if (start.charAt(i) != target.charAt(j)) {
                return false;
            }

            // If the character is 'L', it should be to the right of its position in start
            if (start.charAt(i) == 'L' && i < j) {
                return false;
            }

            // If the character is 'R', it should be to the left of its position in target
            if (start.charAt(i) == 'R' && i > j) {
                return false;
            }

            i++;
            j++;
        }

        // Check if there are any remaining characters in either string
        while (i < n) {
            if (start.charAt(i) != '_') {
                return false;
            }
            i++;
        }

        while (j < n) {
            if (target.charAt(j) != '_') {
                return false;
            }
            j++;
        }

        // If we have reached this point, it's possible to transform start into target
        return true;
    }
}

