                                    replacementCountMap.getOrDefault(sub.charAt(j), 0) + 1);
                        } else {
                            match = false;
                            break;
                        }
                    } else if (mappingMap.containsKey(s.charAt(i + j)) && mappingMap.get(s.charAt(i + j)) == sub.charAt(j)) {
                        // If the current character in 's' is a potential replacement for the character in 'sub'
                        // but it's not directly mapped, we still need to check if this replacement has been done before
                        match = false;
                        break;
                    } else {
                        Character originalChar = getOriginalChar(s.charAt(i + j), mappingMap);
                        if (originalChar != null && originalChar == sub.charAt(j)) {
                            // Check if the character in 'sub' has already been replaced
                            if (!replacedCharsInSub.contains(sub.charAt(j))) {
                                replacedCharsInSub.add(sub.charAt(j));

                                // Update the replacement count map
                                replacementCountMap.put(sub.charAt(j), 
                                        replacementCountMap.getOrDefault(sub.charAt(j), 0) + 1);
                            } else {
                                match = false;
                                break;
                            }
                        } else {
                            match = false;
                            break;
                        }
                    }
                }
            }

            // Check if any character in 'sub' has been replaced more than once
            for (int count : replacementCountMap.values()) {
                if (count > 1) {
                    match = false;
                    break;
                }
            }

            if (match) return true;
        }

        return false;
    }

    private Character getOriginalChar(char c, Map<Character, Character> mappingMap) {
        while (mappingMap.containsKey(c)) {
            c = mappingMap.get(c);
        }
        return c;
    }
}

