public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int peopleAwareOfSecret(int n, int delay, int forget) {
        long[] dp = new long[n + 1];

        // On day 1, one person discovers a secret
        dp[1] = 1;

        for (int i = 2; i <= n; i++) {
            // People who start sharing the secret on this day are those who discovered it 'delay' days ago
            if (i - delay > 0) {
                dp[i] += dp[i - delay];
            }

            // Accumulate sharers from previous days, ensuring they haven't forgotten yet
            for (int j = i - delay + 1; j <= i && j - forget > 0; j++) {
                if(j >= 2) {
                    dp[i] += dp[j];
                }
            }

            // Apply modulo to avoid overflow
            dp[i] %= MOD;
        }

        long sum = 0;
        for (int i = 1; i <= n; i++) {
            if (i - forget > 0) {
                sum += dp[i];
                sum %= MOD;
            } else {
                sum += dp[i];
                sum %= MOD;
            }
        }

        return (int) sum;
    }
}

