public class Solution {
    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        // Calculate the sums of both arrays without any swaps
        int sum1 = 0;
        for (int num : nums1) {
            sum1 += num;
        }

        int sum2 = 0;
        for (int num : nums2) {
            sum2 += num;
        }

        // Ensure that nums1 has the larger or equal sum
        if (sum1 < sum2) {
            int[] temp = nums1;
            nums1 = nums2;
            nums2 = temp;
        }

        int maxScore = Math.max(sum1, sum2);  // Baseline score without any swaps

        // Iterate over all possible subarrays and calculate the potential gain from swapping
        for (int left = 0; left < nums1.length; left++) {
            for (int right = left; right < nums1.length; right++) {
                int subarraySum1 = 0;
                int subarraySum2 = 0;
                for (int i = left; i <= right; i++) {
                    subarraySum1 += nums1[i];
                    subarraySum2 += nums2[i];
                }

                // Calculate the potential gain from swapping this subarray
                int gain = subarraySum2 - subarraySum1;

                // Update maxScore if the current gain results in a higher score
                if (sum1 + gain > maxScore) {
                    maxScore = sum1 + gain;
                }
            }
        }

        return maxScore;
    }
}

