public class Solution {
    public int[][] spiralMatrixIII(int m, int n, ListNode head) {
        int[][] matrix = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                matrix[i][j] = -1;
            }
        }

        int[] directionsX = {0, 1, 0, -1}; // right, down, left, up
        int[] directionsY = {1, 0, -1, 0};
        int dirIndex = 0;
        int row = 0, col = 0;

        while (head != null) {
            if (row < 0 || row >= m || col < 0 || col >= n) {
                throw new RuntimeException("Invalid input");
            }
            matrix[row][col] = head.val;
            head = head.next;

            int nextRow = row + directionsX[dirIndex];
            int nextCol = col + directionsY[dirIndex];

            if (nextRow < 0 || nextRow >= m || nextCol < 0 || nextCol >= n || matrix[nextRow][nextCol] != -1) {
                dirIndex = (dirIndex + 1) % 4;
            }

            row += directionsX[dirIndex];
            col += directionsY[dirIndex];
        }
        return matrix;
    }
}

