// #Medium #Array #Dynamic_Programming #Bit_Manipulation #Backtracking #Bitmask
public class Solution {
    private int minUnfairness = Integer.MAX_VALUE;

    public int distributeCookies(int[] cookies, int k) {
        Arrays.sort(cookies);
        backtrack(cookies, new int[k], 0);
        return minUnfairness;
    }

    private void backtrack(int[] cookies, int[] assigned, int index) {
        if (index == cookies.length) {
            minUnfairness = Math.min(minUnfairness, getMax(assigned));
            return;
        }

        for (int i = 0; i < assigned.length; i++) {
            // Relax the pruning condition to allow more branches to be explored
            if (getMax(assigned) + cookies[index] >= minUnfairness && index == cookies.length - 1) continue;
            assigned[i] += cookies[index];
            backtrack(cookies, assigned, index + 1);
            assigned[i] -= cookies[index];
        }
    }

    private int getMax(int[] arr) {
        int max = Integer.MIN_VALUE;
        for (int num : arr) {
            if (num > max) max = num;
        }
        return max;
    }
}

