// #Hard #Array #Dynamic_Programming #Depth_First_Search #Breadth_First_Search #Matrix #Graph
// #Memoization #Topological_Sort #2022_07_04_Time_43_ms_(100.00%)_Space_89.1_MB_(63.64%)
public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public int countPaths(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        long[][] memo = new long[m][n];

        for (long[] row : memo) {
            Arrays.fill(row, -1);
        }

        long totalPaths = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                totalPaths += dfs(grid, i, j, memo);
                totalPaths %= MOD;
            }
        }

        return (int) totalPaths;
    }

    private long dfs(int[][] grid, int x, int y, long[][] memo) {
        if (memo[x][y] != -1) {
            return memo[x][y];
        }

        long paths = 1;

        for (int[] direction : DIRECTIONS) {
            int newX = x + direction[0];
            int newY = y + direction[1];

            if (newX >= 0 && newX < grid.length && newY >= 0 && newY < grid[0].length && grid[newX][newY] > grid[x][y]) {
                paths += dfs(grid, newX, newY, memo);
                paths %= MOD;
            }
        }

        return memo[x][y] = paths;
    }
}

