import java.util.*;

public class Solution {
    public long kSum(int[] nums, int k) {
        // Generate all possible subsequences and their sums
        PriorityQueue<Long> pq = new PriorityQueue<>((a, b) -> Long.compare(b, a));

        dfs(nums, 0, 0, pq);

        // Get the k-th largest sum from the priority queue
        for (int i = 1; i < k; i++) {
            if (!pq.isEmpty()) {
                pq.poll();
            }
        }

        return !pq.isEmpty() ? pq.peek() : 0;
    }

    private void dfs(int[] nums, int index, long sum, PriorityQueue<Long> pq) {
        if (index == nums.length) {
            pq.offer(sum);
            return;
        }

        // Include the current element in the subsequence
        dfs(nums, index + 1, sum + nums[index], pq);

        // Exclude the current element from the subsequence
        dfs(nums, index + 1, sum, pq);
    }
}

