// #2022_06_30_Time_255_ms_(70.70%)_Space_117.2_MB_(57.14%)
import java.util.*;

public class Solution {
    private int minScore = Integer.MAX_VALUE;
    private ArrayList<Integer>[] graph;

    public int minimumScore(int[] nums, int[][] edges) {
        // Initializing the graph and finding the total XOR
        graph = new ArrayList[nums.length];
        for (int i = 0; i < nums.length; i++) {
            graph[i] = new ArrayList<>();
        }
        // adding the edges
        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }

        int totalXor = 0;
        for (int num : nums) {
            totalXor ^= num;
        }

        // Iterate over each pair of distinct edges in the tree
        for (int i = 0; i < edges.length; i++) {
            for (int j = i + 1; j < edges.length; j++) {
                // Temporarily remove these two edges from the graph
                int xor1 = calculateXORForComponent(graph, nums, edges[i][0], edges[i][1]);
                int xor2 = calculateXORForComponent(graph, nums, edges[j][0], edges[j][1]);
                int xor3 = totalXor ^ xor1 ^ xor2;

                // Calculate the difference between max and min XOR values
                int diff = Math.max(xor1, Math.max(xor2, xor3)) - Math.min(xor1, Math.min(xor2, xor3));

                // Update minScore if a smaller difference is found
                minScore = Math.min(minScore, diff);
            }
        }

        return minScore;
    }

    private int calculateXORForComponent(ArrayList<Integer>[] graph, int[] nums, int node1, int node2) {
        boolean[] visited = new boolean[nums.length];
        return dfs(graph, nums, node1, visited, node2);
    }

    private int dfs(ArrayList<Integer>[] graph, int[] nums, int src, boolean[] visited, int blockedNode) {
        // Setting the value for the current subtree's XOR value
        visited[src] = true;
        int xor = nums[src];
        for (int nbr : graph[src]) {
            if (!visited[nbr] && nbr != blockedNode) {
                // Including the neighbour subtree's XOR value in the XOR value of the subtree
                // rooted at src node
                xor ^= dfs(graph, nums, nbr, visited, blockedNode);
            }
        }
        return xor;
    }
}

