public class Solution {
    public int countSpecialNumbers(int n) {
        char[] str = String.valueOf(n).toCharArray();
        int len = str.length;
        int res = 0;

        // calculate special numbers with less digits than n
        for (int i = 1; i < len; i++) {
            if (i == 1) {
                res += 9; // single digit, excluding 0
            } else {
                res += perm(9, i);
            }
        }

        // calculate special numbers with the same number of digits as n
        boolean[] visited = new boolean[10];
        res += dfs(str, 0, visited);

        return res;
    }

    private int dfs(char[] str, int index, boolean[] visited) {
        if (index == str.length) {
            return 1;
        }

        int res = 0;
        // Determine the upper limit for digit selection based on whether we're at the first digit or not
        int upperLimit = str[index] - '0';
        for (int i = index == 0 ? 1 : 0; i <= upperLimit; i++) {
            if (!visited[i]) {
                visited[i] = true;
                res += dfs(str, index + 1, visited);
                visited[i] = false;
            }
        }

        return res;
    }

    private int perm(int m, int n) {
        if (n > m) return 0;
        int res = 1;
        for (int i = m; i > m - n; i--) {
            res *= i;
        }
        return res;
    }
}

