        for (int j = 2; j <= n; j++) {
            long[] nextDp = new long[maxValue + 1];

            for (int i = 1; i <= maxValue; i++) {
                for (int k = 1; k * i <= maxValue; k++) {
                    nextDp[i * k] = (nextDp[i * k] + dp[i]) % MOD;
                }
            }

            dp = nextDp;
        }

        long sum = 0;

        for (int i = 1; i <= maxValue; i++) {
            sum = (sum + dp[i]) % MOD;
        }

        return (int) sum;
    }
}

