public class Solution {
    public String largestPalindromic(String num) {
        int[] count = new int[10];

        // Count the frequency of each digit
        for (char c : num.toCharArray()) {
            count[c - '0']++;
        }

        StringBuilder sb = new StringBuilder();
        char mid = ' ';

        // Build the first half of the palindrome
        for (int i = 9; i >= 0; i--) {
            if (count[i] % 2 == 1 && mid == ' ') {
                mid = (char) ('0' + i);
            }
            int times = count[i] / 2;
            while (times-- > 0) {
                sb.append((char) ('0' + i));
            }
        }

        // If the number is not empty and does not start with '0', add the second half of the palindrome
        if (!sb.toString().isEmpty() && sb.charAt(0) != '0') {
            StringBuilder reverse = new StringBuilder(sb).reverse();
            return sb.append(mid).append(reverse).toString();
        } else if (mid == ' ') { // If no digits are available, return "0"
            for (int i = 1; i <= 9; i++) {
                if (count[i] > 0) {
                    return String.valueOf(i);
                }
            }
            return "0";
        } else { // If the number starts with '0', only add the middle digit
            return String.valueOf(mid);
        }
    }
}

