public class Solution {
    public String decodeMessage(String key, String message) {
        Map<Character, Character> substitutionTable = new HashMap<>();
        StringBuilder alphabet = new StringBuilder();

        // Create the substitution table
        for (char c : key.toCharArray()) {
            if (c != ' ' && !alphabet.toString().contains(String.valueOf(c))) {
                alphabet.append(c);
            }
        }

        // Fill in any missing letters from the alphabet
        String allAlphabet = "abcdefghijklmnopqrstuvwxyz";
        int index = 0;
        for (char c : allAlphabet.toCharArray()) {
            if (!alphabet.toString().contains(String.valueOf(c))) {
                alphabet.insert(index, c);
            } else {
                index++;
            }
        }

        // Create the substitution table
        String regularAlphabet = "abcdefghijklmnopqrstuvwxyz";
        for (int i = 0; i < 26; i++) {
            substitutionTable.put(alphabet.charAt(i), regularAlphabet.charAt(i));
        }

        // Decode the message using the substitution table
        StringBuilder decodedMessage = new StringBuilder();
        for (char c : message.toCharArray()) {
            if (c == ' ') {
                decodedMessage.append(' ');
            } else {
                decodedMessage.append(substitutionTable.get(c));
            }
        }

        return decodedMessage.toString();
    }
}

