import java.util.PriorityQueue;
import java.util.Arrays;

public class Solution {
    public int[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        boolean[] removed = new boolean[n];
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> Integer.compare(b, a));

        // Initialize the priority queue with segment sums
        for (int i = 0; i < n; i++) {
            if (!removed[i]) {
                int sum = 0;
                for (int j = i; j < n && !removed[j]; j++) {
                    sum += nums[j];
                }
                pq.offer(sum);
            }
        }

        int[] result = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            removed[removeQueries[i]] = true;

            // Clear the priority queue
            PriorityQueue<Integer> tempPq = new PriorityQueue<>((a, b) -> Integer.compare(b, a));

            // Recalculate segment sums after removal
            int sum = 0;
            for (int j = 0; j < n; j++) {
                if (!removed[j]) {
                    sum += nums[j];
                } else {
                    if (sum > 0) tempPq.offer(sum);
                    sum = 0;
                }
            }

            // Add the last segment sum
            if (sum > 0) tempPq.offer(sum);

            pq = tempPq;

            // Check for empty priority queue before calling peek()
            if (!pq.isEmpty()) {
                result[i] = pq.peek();
            } else {
                // Handle the case where all elements are removed
                result[i] = 0;
            }
        }

        return result;
    }
}

