        }

        long lastSum = 0;
        int lastIndex = -1;
        int groupSize = 0; 
        for (int i = 1; i <= k; i++) {
            if(i == 1) {
                int start = lastIndex + 1, end = grades.length;
                while (start < end) {
                    int mid = start + (end - start) / 2;
                    long sum = prefixSum[mid] - prefixSum[lastIndex + 1];
                    if (sum > lastSum && mid - lastIndex - 1 >= groupSize) {
                        end = mid;
                    } else {
                        start = mid + 1;
                    }
                }
                if (start == grades.length || prefixSum[start] - prefixSum[lastIndex + 1] <= lastSum || start - lastIndex - 1 < groupSize) { 
                    return false;
                }
                lastSum = prefixSum[start] - prefixSum[lastIndex + 1];
                lastIndex = start-1;
                groupSize++; 
            } else {
                int start = lastIndex + 1, end = grades.length;
                while (start < end) {
                    int mid = start + (end - start) / 2;
                    long sum = prefixSum[mid] - prefixSum[lastIndex + 1];
                    if (sum > lastSum && mid - lastIndex - 1 > groupSize) {
