public class Solution {
    public double calculateTax(int[][] brackets, int income) {
        double tax = 0.0;
        int prevUpper = 0;

        for (int[] bracket : brackets) {
            int upper = bracket[0];
            int percent = bracket[1];

            if (income > upper) {
                // If the income is greater than the current upper bound, 
                // calculate tax for the entire range of this bracket
                tax += (upper - prevUpper) * ((double) percent / 100);
            } else {
                // If the income is less than or equal to the current upper bound, 
                // calculate tax only up to the income amount and break the loop
                tax += (income - prevUpper) * ((double) percent / 100);
                break;
            }

            prevUpper = upper;
        }

        return tax;
    }
}

