// #Medium #Array #Matrix #Bit_Manipulation #Backtracking #Enumeration
// #2022_09_14_Time_1_ms_(100.00%)_Space_40.7_MB_(93.95%)
public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        int n = matrix[0].length;

        // Initialize a set to store the rows that are covered
        Set<Integer> coveredRows = new HashSet<>();

        // Generate all possible combinations of columns
        List<List<Integer>> columnCombinations = generateColumnCombinations(n, numSelect);

        int maxCoveredRows = 0;

        for (List<Integer> combination : columnCombinations) {
            coveredRows.clear();

            // Check each row to see if it's covered by the current combination
            for (int i = 0; i < m; i++) {
                boolean isRowCovered = true;

                for (int j = 0; j < n; j++) {
                    if (matrix[i][j] == 1 && !combination.contains(j)) {
                        isRowCovered = false;
                        break;
                    }
                }

                if (isRowCovered) {
                    coveredRows.add(i);
                }
            }

            // Update the maximum number of covered rows
            maxCoveredRows = Math.max(maxCoveredRows, coveredRows.size());
        }

        return maxCoveredRows;
    }

    private List<List<Integer>> generateColumnCombinations(int n, int numSelect) {
        List<List<Integer>> combinations = new ArrayList<>();
        backtrack(combinations, new ArrayList<>(), 0, n, numSelect);
        return combinations;
    }

    private void backtrack(List<List<Integer>> combinations, List<Integer> tempList, int start, int n, int numSelect) {
        if (tempList.size() == numSelect) {
            combinations.add(new ArrayList<>(tempList));
        } else {
            for (int i = start; i < n; i++) {
                tempList.add(i);
                backtrack(combinations, tempList, i + 1, n, numSelect);
                tempList.remove(tempList.size() - 1);
            }
        }
    }
}

