public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        for (int i = 0; i < nums1.length; i++) {
            int diff = Math.abs(nums1[i] - nums2[i]);
            if (diff > 0) {
                pq.offer(diff);
            }
        }

        long res = 0;
        while (!pq.isEmpty() && k1 + k2 > 0) {
            int curDiff = pq.poll();
            // Calculate the reduction in squared difference for modifying nums1 and nums2
            long reduceNums1 = (long)curDiff * curDiff - (long)(curDiff - 1) * (curDiff - 1);
            long reduceNums2 = (long)curDiff * curDiff - (long)(curDiff + 1) * (curDiff + 1);

            if (k1 > 0 && k2 > 0) {
                if (reduceNums1 >= reduceNums2) {
                    // Modify nums1
                    k1--;
                    curDiff -= 1;
                } else {
                    // Modify nums2
                    k2--;
                    curDiff += 1;
                }
            } else if (k1 > 0) {
                // Modify nums1
                k1--;
                curDiff -= 1;
            } else if (k2 > 0) {
                // Modify nums2
                k2--;
                curDiff += 1;
            }

            if (curDiff > 0) {
                pq.offer(curDiff);
            }
        }

        while (!pq.isEmpty()) {
            int curDiff = pq.poll();
            res += (long)curDiff * curDiff;
        }

        return res;
    }
}

