// #Medium #Array #Math #Bit_Manipulation 
public class Solution {
    public int maximumXOR(int[] nums) {
        if (nums.length == 0) return 0;

        // Create a Trie to store binary representations of numbers in the array
        Trie trie = new Trie();
        for (int num : nums) {
            addNumToTrie(trie, num);
        }

        int result = 0;
        for (int num : nums) {
            // For each number, find its maximum XOR value using the Trie
            result = Math.max(result, findMaxXORInTrie(trie, num));
        }

        return result;
    }

    private void addNumToTrie(Trie trie, int num) {
        TrieNode current = trie.root;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (current.children[bit] == null) {
                current.children[bit] = new TrieNode();
            }
            current = current.children[bit];
        }
    }

    private int findMaxXORInTrie(Trie trie, int num) {
        TrieNode current = trie.root;
        int result = 0;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            // Try to go in the opposite direction of the current bit
            if (current.children[1 - bit] != null) {
                result |= (1 << i);
                current = current.children[1 - bit];
            } else {
                current = current.children[bit];
            }
        }
        return result;
    }

    private static class Trie {
        TrieNode root;

        public Trie() {
            this.root = new TrieNode();
        }
    }

    private static class TrieNode {
        TrieNode[] children;

        public TrieNode() {
            this.children = new TrieNode[2];
        }
    }
}

