public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int countHousePlacements(int n) {
        long[] dp = new long[n + 1];
        dp[0] = 1; // base case: no plots
        dp[1] = 2; // base case: one plot

        for (int i = 2; i <= n; i++) {
            // a house can be placed on the current plot if there is no house on the previous plot
            // or no house can be placed on the current plot
            dp[i] = (dp[i - 1] + dp[i - 2]) % MOD;
        }

        // since there are two sides of the street, we need to square the result
        return (int) ((dp[n] * dp[n]) % MOD);
    }
}

