import java.util.*;

public class Solution {
    public int reachableNodes(int n, int[][] edges, int[] restricted) {
        // Create an adjacency list to represent the graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        // Populate the adjacency list with edges
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            graph.get(u).add(v);
            graph.get(v).add(u);
        }

        // Create a set to store restricted nodes for efficient lookup
        Set<Integer> restrictedSet = new HashSet<>();
        for (int node : restricted) {
            restrictedSet.add(node);
        }

        // Initialize the count of reachable nodes with 1 (node 0)
        int count = 1;

        // Perform DFS from node 0 to mark all reachable nodes
        boolean[] visited = new boolean[n];
        dfs(graph, 0, restrictedSet, visited);

        // Count all nodes that are not restricted and have been visited
        for (int i = 0; i < n; i++) {
            if (!restrictedSet.contains(i) && visited[i]) {
                count++;
            }
        }

        return count - 1; // Subtract 1 because we counted node 0 twice
    }

    private void dfs(List<List<Integer>> graph, int node, Set<Integer> restrictedSet, boolean[] visited) {
        visited[node] = true;

        for (int neighbor : graph.get(node)) {
            if (!restrictedSet.contains(neighbor) && !visited[neighbor]) {
                dfs(graph, neighbor, restrictedSet, visited);
            }
        }
    }
}

