public class Solution {
    public int minimumNumbers(int num, int k) {
        if (num == 0) return 0;

        int result = Integer.MAX_VALUE;

        for (int i = 1; num >= i * k; i++) {
            // Calculate the remaining sum after subtracting i * k from num
            int remainingSum = num - i * k;

            // Check if the remaining sum can be formed using numbers with a units digit of k
            if (remainingSum % 10 == 0 || remainingSum == 0) {
                // Update the minimum possible size of the set
                result = Math.min(result, i);
            }
        }

        return result == Integer.MAX_VALUE ? -1 : result;
    }
}

