import java.util.Arrays;

public class Solution {
    public int[] answerQueries(int[] nums, int[] queries) {
        // we can sort the nums because the order of the subsequence does not matter
        Arrays.sort(nums);

        // calculate prefix sum for nums array
        int n = nums.length;
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        // initialize answer array with zeros
        int m = queries.length;
        int[] answer = new int[m];

        // iterate over each query and find the maximum size of subsequence
        for (int i = 0; i < m; i++) {
            int target = queries[i];
            int left = 0, right = n;

            // use binary search to find the largest prefix sum that is less than or equal to the target
            while (left < right) {
                int mid = left + (right - left + 1) / 2;
                if (prefixSum[mid] <= target) {
                    left = mid;
                } else {
                    right = mid - 1;
                }
            }

            // update the answer array with the maximum size of subsequence
            answer[i] = left;
        }

        return answer;
    }
}

