public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();

        // Initialize dp array with -1
        Integer[][][] dp = new Integer[n + 1][n + 1][32];

        return dfs(s, k, 0, 0, 0, dp);
    }

    private int dfs(String s, int target, int index, int len, long num, Integer[][][] dp) {
        if (index == s.length()) {
            return len;
        }

        if (dp[index][len][(int)num] != null) {
            return dp[index][len][(int)num];
        }

        // Not include current character
        int notInclude = dfs(s, target, index + 1, len, num, dp);

        // Include current character
        if (s.charAt(index) == '0') {
            long newNum = num * 2;
            if (newNum <= target) {
                int include = dfs(s, target, index + 1, len + 1, newNum, dp);
                notInclude = Math.max(notInclude, include);
            }
        } else if (s.charAt(index) == '1') {
            long newNum = num * 2 + 1;
            if (newNum <= target) {
                int include = dfs(s, target, index + 1, len + 1, newNum, dp);
                notInclude = Math.max(notInclude, include);
            }
        }

        return dp[index][len][(int)num] = notInclude;
    }
}

