import java.util.HashSet;

public class Solution {
    public int countDistinctIntegers(int[] nums) {
        HashSet<Integer> set = new HashSet<>();

        // Add original integers to the set
        for (int num : nums) {
            set.add(num);
        }

        // Reverse each integer and add it to the set
        for (int num : nums) {
            int reversedNum = reverseInteger(num);
            set.add(reversedNum);
        }

        return set.size();
    }

    private int reverseInteger(int num) {
        int sign = 1;
        if (num < 0) {
            sign = -1;
            num *= -1;
        }

        int reversedNum = 0;
        while (num > 0) {
            int digit = num % 10;
            reversedNum = reversedNum * 10 + digit;
            num /= 10;
        }

        return sign * reversedNum;
    }
}

