public class Solution {
    public String smallestNumber(String pattern) {
        if (pattern == null || pattern.length() == 0) {
            return "";
        }

        StringBuilder sb = new StringBuilder();
        boolean[] used = new boolean[10];

        for (int i = 1; i <= 9; i++) {
            if (!dfs(pattern, 0, sb, used, i)) {
                continue;
            }
            return sb.toString();
        }

        throw new IllegalArgumentException("Invalid pattern. Cannot find a valid sequence.");
    }

    private boolean dfs(String pattern, int index, StringBuilder sb, boolean[] used, int num) {
        if (index == pattern.length()) {
            // Append any remaining unused digits in ascending order
            for (int i = 1; i <= 9; i++) {
                if (!used[i]) {
                    sb.append((char)(i + '0'));
                }
            }
            return true;
        }

        if (used[num]) {
            return false;
        }

        used[num] = true;
        sb.append((char)(num + '0'));

        if (pattern.charAt(index) == 'I') {
            for (int i = num + 1; i <= 9; i++) {
                if (!dfs(pattern, index + 1, sb, used, i)) {
                    continue;
                }
                return true;
            }
        } else {
            for (int i = 1; i < num; i++) {
                if (!dfs(pattern, index + 1, sb, used, i)) {
                    continue;
                }
                return true;
            }
        }

        used[num] = false;
        sb.deleteCharAt(sb.length() - 1);
        return false;
    }
}

