public class Solution {
    public int deleteGreatestValue(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int ans = 0;

        // Iterate through each column
        for (int i = 0; i < n; i++) {
            int[] maxValues = new int[m];

            // Find the maximum value in each row across all remaining columns
            for (int j = 0; j < m; j++) {
                int maxValue = Integer.MIN_VALUE;

                // Iterate through all columns to find the maximum value in this row
                for (int k = 0; k < n; k++) {
                    if (grid[j][k] > maxValue) {
                        maxValue = grid[j][k];
                    }
                }

                maxValues[j] = maxValue;
            }

            // Update the answer with the maximum of deleted elements
            int maxDeletedValue = Arrays.stream(maxValues).max().getAsInt();
            ans += maxDeletedValue;

            // "Delete" (or mark as deleted) these maximum values from their rows
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < n; k++) {
                    if (grid[j][k] == maxValues[j]) {
                        grid[j][k] = Integer.MIN_VALUE;
                        break;
                    }
                }
            }
        }

        return ans;
    }
}

