import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public TreeNode reverseOddLevels(TreeNode root) {
        if (root == null) return null;

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int level = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            List<Integer> values = new ArrayList<>();

            // Store the nodes at current level
            TreeNode[] nodesAtCurrentLevel = new TreeNode[size];
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                values.add(node.val);
                nodesAtCurrentLevel[i] = node;

                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }

            // Reverse the values at odd levels
            if ((level + 1) % 2 == 0) {
                int j = size - 1;
                for (int i = 0; i < size; i++) {
                    nodesAtCurrentLevel[i].val = values.get(j--);
                }
            }

            level++;
        }

        return root;
    }

    public static TreeNode create(List<Integer> values) {
        if (values.isEmpty()) return null;

        Queue<TreeNode> queue = new LinkedList<>();
        TreeNode root = new TreeNode(values.get(0));
        queue.offer(root);

        int index = 1;
        while (!queue.isEmpty() && index < values.size()) {
            TreeNode node = queue.poll();
            if (index < values.size()) {
                node.left = new TreeNode(values.get(index++));
                queue.offer(node.left);
            }
            if (index < values.size()) {
                node.right = new TreeNode(values.get(index++));
                queue.offer(node.right);
            }
        }

        return root;
    }
}

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

