import java.util.Arrays;

public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);

        int result = -1;

        // Iterate over each bus
        for (int i = 0; i < buses.length; i++) {
            int currentCapacity = 0;

            // Fill the current bus with passengers
            for (int j = 0; j < passengers.length && currentCapacity < capacity; j++) {
                if (passengers[j] <= buses[i]) {
                    currentCapacity++;
                }
            }

            // If the bus is not full, try to find a time slot before the last passenger or the bus departure
            if (currentCapacity < capacity) {
                result = Math.max(result, buses[i]);

                // Check for available time slots between passengers' arrivals and the bus departure
                int lastPassengerIndex = -1;
                for (int j = 0; j < passengers.length; j++) {
                    if (passengers[j] > buses[i]) break;
                    if (j == 0 || passengers[j - 1] < buses[i]) {
                        // Consider the time just before this passenger arrives
                        result = Math.max(result, passengers[j] - 1);
                    }
                    lastPassengerIndex = j;
                }

                // If there's a gap between the last passenger and the bus departure, consider it
                if (lastPassengerIndex != -1 && passengers[lastPassengerIndex] < buses[i]) {
                    result = Math.max(result, passengers[lastPassengerIndex]);
                }
            } 
            // If the bus is full, try to find a time slot before the last passenger
            else {
                for (int j = 0; j < passengers.length; j++) {
                    if (passengers[j] > buses[i]) break;
                    if (j == 0 || passengers[j - 1] < buses[i]) {
                        result = Math.max(result, passengers[j] - 1);
                    }
                }
            }
        }

        return result == -1 ? buses[buses.length - 1] : result;
    }
}

