public class Solution {
    public int longestSubarray(int[] nums) {
        int n = nums.length;
        int maxVal = Integer.MIN_VALUE;

        // Find the maximum value in the array
        for (int num : nums) {
            maxVal = Math.max(maxVal, num);
        }

        // Initialize variables to store the longest subarray length and current window's bitwise AND
        int maxLength = 0;
        int currAnd = maxVal;

        // Iterate over all possible subarrays
        for (int i = 0; i < n; i++) {
            currAnd = nums[i];
            for (int j = i + 1; j <= n; j++) {
                if (i == j - 1) {
                    maxLength = Math.max(maxLength, j - i);
                } else {
                    // Calculate the bitwise AND of the current subarray
                    int tempAnd = currAnd;
                    for (int k = i + 1; k < j; k++) {
                        tempAnd &= nums[k];
                    }

                    // Update maxLength if the bitwise AND equals maxVal and the subarray is longer
                    if (tempAnd == maxVal) {
                        maxLength = Math.max(maxLength, j - i);
                    }
                }
            }
        }

        return maxLength;
    }
}

