public class Solution {
    /**
     * Returns the id of the employee that worked the task with the longest time.
     * If there is a tie between two or more employees, returns the smallest id among them.
     *
     * @param n    The number of employees
     * @param logs A 2D integer array where logs[i] = [id_i, leaveTime_i]
     *             id_i is the id of the employee that worked on the i-th task,
     *             and leaveTime_i is the time at which the employee finished the i-th task.
     * @return The id of the employee with the longest working time
     */
    public int hardestWorker(int n, int[][] logs) {
        // Initialize variables to keep track of the maximum time spent by an employee and their id
        int maxTime = 0;
        int id = -1;

        // Initialize a variable to store the previous task's end time
        int prevTime = 0;

        // Iterate through each log entry in the logs array
        for (int[] log : logs) {
            // Extract the current employee's id and their leave time from the log entry
            int currId = log[0];
            int currLeaveTime = log[1];

            // Calculate the time spent by the current employee on the task
            int timeSpent = currLeaveTime - prevTime;

            // Check if the current employee has spent more time than the previous maximum,
            // or if they have spent the same amount of time but have a smaller id
            if (timeSpent > maxTime || (timeSpent == maxTime && (id == -1 || id > currId))) {
                // Update the maximum time and the corresponding employee's id
                maxTime = timeSpent;
                id = currId;
            }

            // Update the previous task's end time for the next iteration
            prevTime = currLeaveTime;
        }

        // Return the id of the employee with the longest working time
        return id;
    }
}

