                    colOnes[j]++;
                }
            }
        }

        // Calculate the difference matrix
        int[][] diff = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                diff[i][j] = rowOnes[i] + colOnes[j] - (n - rowOnes[i]) - (m - colOnes[j]);
            }
        }

        return diff;
    }
}

