// #Medium #Array #Sorting #Greedy #Two_Pointers #Heap_Priority_Queue #Prefix_Sum
// #2022_10_23_Time_144_ms_(71.27%)_Space_151.1_MB_(13.30%)
public class Solution {
    public int minGroups(int[][] intervals) {
        if (intervals.length == 0) return 0;

        // Sort the intervals by their start time
        Arrays.sort(intervals, (a, b) -> a[0] - b[0]);

        // Initialize a priority queue to store the end times of the intervals
        PriorityQueue<Integer> pq = new PriorityQueue<>();

        for (int[] interval : intervals) {
            // If the current interval starts after the earliest end time, 
            // it means we can reuse the group with the earliest end time
            if (!pq.isEmpty() && interval[0] >= pq.peek()) {
                pq.poll();
            }
            // Add the end time of the current interval to the priority queue
            pq.offer(interval[1]);
        }

        // The size of the priority queue is the minimum number of groups needed
        return pq.size();
    }
}

