import java.util.HashMap;

public class Solution {
    public int deleteString(String s) {
        int n = s.length();
        int[] dp = new int[n + 1];
        for (int i = n - 1; i >= 0; --i) {
            dp[i] = 1;
            for (int j = i + 1; j <= n; ++j) {
                if (2 * j - i > n) break;
                String s1 = s.substring(i, j);
                String s2 = s.substring(j, 2 * j - i);
                if (s1.equals(s2)) dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
        return dp[0];
    }
}

