public class Solution {
    public int countDaysTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

        // Convert dates to day of year
        int arriveAliceDayOfYear = getDayOfYear(arriveAlice, daysInMonth);
        int leaveAliceDayOfYear = getDayOfYear(leaveAlice, daysInMonth);
        int arriveBobDayOfYear = getDayOfYear(arriveBob, daysInMonth);
        int leaveBobDayOfYear = getDayOfYear(leaveBob, daysInMonth);

        // Calculate overlap
        int startOverlap = Math.max(arriveAliceDayOfYear, arriveBobDayOfYear);
        int endOverlap = Math.min(leaveAliceDayOfYear, leaveBobDayOfYear);

        // Return number of overlapping days
        return Math.max(endOverlap - startOverlap + 1, 0);
    }

    private int getDayOfYear(String date, int[] daysInMonth) {
        String[] parts = date.split("-");
        int month = Integer.parseInt(parts[0]) - 1;
        int day = Integer.parseInt(parts[1]);

        int sum = 0;
        for (int i = 0; i < month; i++) {
            sum += daysInMonth[i];
        }
        return sum + day;
    }
}

