        int[] result = new int[n];

        for (int i = 0; i < n; i++) {
            int maxOr = nums[i];
            int minLen = 1;

            for (int j = i; j < n; j++) {
                int or = 0;
                for (int k = i; k <= j; k++) {
                    or |= nums[k];
                }
                if (or > maxOr) {
                    maxOr = or;
                    minLen = j - i + 1;
                } else if (or == maxOr && j - i + 1 < minLen) {
                    minLen = j - i + 1;
                }
            }

            result[i] = minLen;
        }

        return result;
    }
}

