public class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        Map<String, Long> creatorViews = new HashMap<>();
        Map<String, Integer> maxViewIndex = new HashMap<>();

        for (int i = 0; i < creators.length; i++) {
            creatorViews.put(creators[i], creatorViews.getOrDefault(creators[i], 0L) + views[i]);
            if (!maxViewIndex.containsKey(creators[i]) || views[i] > views[maxViewIndex.get(creators[i])]) {
                maxViewIndex.put(creators[i], i);
            } else if (views[i] == views[maxViewIndex.get(creators[i])] && ids[i].compareTo(ids[maxViewIndex.get(creators[i])]) < 0) {
                maxViewIndex.put(creators[i], i);
            }
        }

        long maxViews = -1;
        for (long view : creatorViews.values()) {
            if (view > maxViews) {
                maxViews = view;
            }
        }

        List<List<String>> result = new ArrayList<>();
        for (Map.Entry<String, Long> entry : creatorViews.entrySet()) {
            if (entry.getValue() == maxViews) {
                List<String> list = new ArrayList<>();
                list.add(entry.getKey());
                list.add(ids[maxViewIndex.get(entry.getKey())]);
                result.add(list);
            }
        }

        return result;
    }
}

