// #2023_01_27_Time_13_ms_(92.82%)_Space_101.5_MB_(78.71%)
import java.util.*;

public class Solution {
    public int minScore(int n, int[][] roads) {
        Arrays.sort(roads, (a, b) -> a[2] - b[2]);

        UnionFind uf = new UnionFind(n + 1);

        for (int[] road : roads) {
            if (uf.union(road[0], road[1], n)) {
                return road[2];
            }
        }

        throw new RuntimeException("No path found");
    }

    private static class UnionFind {
        int[] parent;
        int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public boolean union(int x, int y, int targetCity) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) {
                return false;
            }

            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }

            return find(1) == find(targetCity);
        }
    }
}

