import java.util.*;

public class Solution {
    public int maxStarSum(int[] nodeValues, int[][] edges, int maxNumberOfEdges) {
        Map<Integer, List<Integer>> graph = new HashMap<>();

        // Build the graph
        for (int[] edge : edges) {
            if (!graph.containsKey(edge[0])) {
                graph.put(edge[0], new ArrayList<>());
            }
            if (!graph.containsKey(edge[1])) {
                graph.put(edge[1], new ArrayList<>());
            }
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int maxStarSum = Integer.MIN_VALUE;

        // Iterate over each node in the graph
        for (int i = 0; i < nodeValues.length; i++) {
            PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> Integer.compare(nodeValues[b], nodeValues[a]));

            // Add all neighbors of the current node to the priority queue
            if (graph.containsKey(i)) {
                for (int neighbor : graph.get(i)) {
                    pq.offer(neighbor);
                }
            }

            int starSum = nodeValues[i];
            int edgeCount = 0;

            // Select the top k edges with the highest values and add them to the star sum
            while (!pq.isEmpty() && edgeCount < maxNumberOfEdges) {
                starSum += nodeValues[pq.poll()];
                edgeCount++;
            }

            // Update the maximum star sum if necessary
            maxStarSum = Math.max(maxStarSum, starSum);
        }

        return maxStarSum;
    }
}

