        for (int[] road : roads) {
            graph[road[0]].add(road[1]);
            graph[road[1]].add(road[0]);
        }

        return dfs(graph, 0, -1, seats);
    }

    private long dfs(ArrayList<Integer>[] graph, int node, int parent, int seats) {
        long total = 0;

        // Count the number of people in the subtree rooted at this node
        int people = 1;
        for (int child : graph[node]) {
            if (child != parent) {
                long temp = dfs(graph, child, node, seats);
                total += temp;
                people += (int)temp;
            }
        }

        // If we are not the capital city, add the fuel cost to travel to the parent
        if (parent != -1) {
            total += (people + seats - 1) / seats; // Ceiling division
        }

        return total;
    }
}

