// #Medium #Array #Greedy #Binary_Search #2023_02_12_Time_1_ms_(100.00%)_Space_55.8_MB_(66.50%)
public class Solution {
    public int maxJump(int[] stones) {
        int n = stones.length;
        int left = 0, right = stones[n - 1] - stones[0];

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canReach(stones, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }

    private boolean canReach(int[] stones, int maxJump) {
        int n = stones.length;
        boolean[] visitedForward = new boolean[n];
        boolean[] visitedBackward = new boolean[n];
        visitedForward[0] = true;

        for (int i = 0; i < n - 1; i++) {
            if (!visitedForward[i]) continue;

            for (int j = i + 1; j < n; j++) {
                if (stones[j] - stones[i] <= maxJump) {
                    visitedForward[j] = true;
                }
            }
        }

        // Check if we can reach the last stone
        if (!visitedForward[n - 1]) return false;

        visitedBackward[n - 1] = true;

        for (int i = n - 1; i > 0; i--) {
            if (!visitedBackward[i]) continue;

            for (int j = i - 1; j >= 0; j--) {
                if (stones[i] - stones[j] <= maxJump) {
                    visitedBackward[j] = true;
                }
            }
        }

        // Check if we can return to the first stone
        return visitedBackward[0];
    }
}

