import java.util.Arrays;

public class Solution {
    public long dividePlayers(int[] skill) {
        Arrays.sort(skill);
        int n = skill.length;

        // Check if the length of the array is even
        if (n % 2 != 0) return -1; 

        // Calculate the total sum of skills
        long totalSum = 0;
        for (int s : skill) {
            totalSum += s;
        }

        // Check divisibility by the number of teams
        int numTeams = n / 2;
        if (totalSum % numTeams != 0) return -1;

        // Determine the target sum for each team
        long targetSum = totalSum / numTeams;

        long chemistrySum = 0;
        int left = 0;
        int right = n - 1;

        while (left < right) {
            if ((long) skill[left] + skill[right] == targetSum) {
                chemistrySum += (long) skill[left] * skill[right];
                left++;
                right--;
            } else if ((long) skill[left] + skill[right] < targetSum) {
                left++;
            } else {
                right--;
            }
        }

        // If all players were successfully paired, return the total chemistry sum
        return left >= right ? chemistrySum : -1;
    }
}

