import java.util.Arrays;

public class Solution {
    public int maxPalindromes(String s, int k) {
        int n = s.length();

        // Handle edge case where string length is less than k
        if (n < k) {
            return 0;
        }

        boolean[][] isPalindrome = new boolean[n][n];

        // Initialize the diagonal of the 2D array to true
        for (int i = 0; i < n; i++) {
            isPalindrome[i][i] = true;
        }

        // Check for substrings of length 2
        for (int i = 0; i < n - 1; i++) {
            if (s.charAt(i) == s.charAt(i + 1)) {
                isPalindrome[i][i + 1] = true;
            }
        }

        // Check for lengths greater than 2
        for (int length = 3; length <= n; length++) {
            for (int i = 0; i < n - length + 1; i++) {
                int j = i + length - 1;
                if (s.charAt(i) == s.charAt(j) && isPalindrome[i + 1][j - 1]) {
                    isPalindrome[i][j] = true;
                }
            }
        }

        // Initialize the dp array
        int[] dp = new int[n];
        Arrays.fill(dp, 0);

        for (int i = 0; i < n; i++) {
            if (isPalindrome[0][i] && i + 1 >= k) {
                dp[i] = 1;
            }

            // Check all possible previous indices
            for (int j = 0; j < i; j++) {
                // Check if there's a palindromic substring from index j to i
                if (isPalindrome[j][i] && i - j + 1 >= k) {
                    dp[i] = Math.max(dp[i], (j == 0 ? 0 : dp[j - 1]) + 1);
                }
            }
        }

        // Return the maximum count
        return dp[n - 1];
    }
}

