    public int minimizeXor(int num1, int num2) {
        // Calculate the maximum possible value for x
        int maxVal = Math.max(num1, num2);

        // Initialize variables to store the minimum XOR result and the corresponding x
        int minResult = Integer.MAX_VALUE;
        int optimalX = 0;

        // Iterate over all integers up to maxVal (inclusive)
        for (int x = 0; x <= maxVal; x++) {
            // Check if x has the same number of set bits as num2
            if (Integer.bitCount(x) == Integer.bitCount(num2)) {
                // Calculate the XOR result between x and num1
                int xorResult = x ^ num1;

                // Update minResult and optimalX if a smaller XOR result is found
                if (xorResult < minResult) {
                    minResult = xorResult;
                    optimalX = x;
                }
            }
        }

        return optimalX;
    }
}

