import java.util.*;

public class Solution {
    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        Arrays.sort(edges, Comparator.comparingInt(a -> Math.max(vals[a[0]], vals[a[1]])));

        UnionFind uf = new UnionFind(vals.length);
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int i = 0; i < vals.length; i++) {
            countMap.put(i, 1);
        }

        int result = 0;

        // Count single-node paths
        for (int val : vals) {
            result++; 
        }

        for (int[] edge : edges) {
            if (vals[edge[0]] == vals[edge[1]]) {
                int rootX = uf.find(edge[0]);
                int rootY = uf.find(edge[1]);

                // Count paths within each component before merging
                result += countPaths(vals, uf, countMap, edge[0], edge[1], vals[edge[0]]);
                if (rootX != rootY) {
                    mergeComponents(uf, countMap, rootX, rootY);
                }
            } else if (vals[edge[0]] < vals[edge[1]]) {
                int rootX = uf.find(edge[0]);
                int rootY = uf.find(edge[1]);

                // Count paths within each component before merging
                result += countPaths(vals, uf, countMap, edge[0], edge[1], vals[edge[0]]);
                if (rootX != rootY) {
                    mergeComponents(uf, countMap, rootX, rootY);
                }
            } else {
                int rootX = uf.find(edge[0]);
                int rootY = uf.find(edge[1]);

                // Count paths within each component before merging
                result += countPaths(vals, uf, countMap, edge[0], edge[1], vals[edge[1]]);
                if (rootX != rootY) {
                    mergeComponents(uf, countMap, rootX, rootY);
                }
            }
        }

        return result;
    }

    private void mergeComponents(UnionFind uf, Map<Integer, Integer> countMap, int rootX, int rootY) {
        if (countMap.containsKey(rootX) && countMap.containsKey(rootY)) {
            if (countMap.get(rootX) < countMap.get(rootY)) {
                uf.union(rootX, rootY);
                countMap.put(rootY, countMap.get(rootX) + countMap.get(rootY));
                countMap.remove(rootX);
            } else {
                uf.union(rootY, rootX);
                countMap.put(rootX, countMap.get(rootX) + countMap.get(rootY));
                countMap.remove(rootY);
            }
        } else if (countMap.containsKey(rootX)) {
            uf.union(rootY, rootX);
        } else if (countMap.containsKey(rootY)) {
            uf.union(rootX, rootY);
        }
    }

    private int countPaths(int[] vals, UnionFind uf, Map<Integer, Integer> countMap, int start, int end, int maxValue) {
        Set<String> visited = new HashSet<>();

        return dfs(vals, uf, countMap, start, end, maxValue, visited);
    }

    private int dfs(int[] vals, UnionFind uf, Map<Integer, Integer> countMap, int current, int end, int maxValue, Set<String> visited) {
        if (current == end && vals[current] <= maxValue) {
            return 1;
        }

        String key = current + "," + end;
        if (visited.contains(key)) {
            return 0;
        }

        visited.add(key);

        int count = 0;
        for (int next : getNeighbors(vals, uf, countMap, current)) {
            if (vals[next] <= maxValue) {
                count += dfs(vals, uf, countMap, next, end, maxValue, visited);
            }
        }

        return count;
    }

    private List<Integer> getNeighbors(int[] vals, UnionFind uf, Map<Integer, Integer> countMap, int node) {
        List<Integer> neighbors = new ArrayList<>();
        for (int i = 0; i < vals.length; i++) {
            if (uf.find(node) == uf.find(i) && countMap.containsKey(i)) {
                neighbors.add(i);
            }
        }

        return neighbors;
    }

    private static class UnionFind {
        int[] parent;

        public UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                parent[rootY] = rootX;
            }
        }

        public boolean isRoot(int x) {
            return parent[x] == x;
        }

        private int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }
    }
}

