    public int[] findArray(int[] pref) {
        int n = pref.length;
        int[] arr = new int[n];

        // The first element of the array is equal to the first element of the prefix
        arr[0] = pref[0];

        // Calculate each element in the array by XORing the corresponding prefix with the previous prefix
        for (int i = 1; i < n; i++) {
            arr[i] = pref[i - 1] ^ pref[i];
