import java.util.*;

public class Solution {
    public int magnificentSets(int n, int[][] edges) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n + 1; i++) {
            graph.add(new ArrayList<>());
        }

        // Build the graph
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int maxGroups = -1;

        // Iterate over all possible group sizes
        for (int groupSize = 1; groupSize <= n; groupSize++) {
            if (n % groupSize == 0) {
                boolean isValidGrouping = true;

                // Check if the graph can be divided into groups of size 'groupSize'
                int[] color = new int[n + 1];
                Arrays.fill(color, -1);

                for (int i = 1; i <= n; i++) {
                    if (color[i] == -1) {
                        Queue<Integer> queue = new LinkedList<>();
                        queue.offer(i);
                        color[i] = 0;

                        while (!queue.isEmpty() && isValidGrouping) {
                            int node = queue.poll();

                            for (int neighbor : graph.get(node)) {
                                if (color[neighbor] == -1) {
                                    // Assign the next group to the neighbor
                                    color[neighbor] = (color[node] + 1) % groupSize;
                                    queue.offer(neighbor);
                                } else if ((Math.abs(color[neighbor] - color[node]) != 1 && 
                                            Math.abs(color[neighbor] - color[node]) != groupSize - 1)) {
                                    isValidGrouping = false;
                                    break;
                                }
                            }
                        }
                    }
                }

                // If the graph can be divided into groups of size 'groupSize', update maxGroups
                if (isValidGrouping) {
                    maxGroups = Math.max(maxGroups, n / groupSize);
                }
            }
        }

        return maxGroups;
    }
}

