// #Easy #String #Hash_Table #Counting #2022_11_18_Time_1_ms_(75.41%)_Space_41.9_MB_(50.90%)
public class Solution {
    public boolean equalFrequency(String word) {
        Map<Character, Integer> frequencyMap = new HashMap<>();

        // Count the frequency of each character
        for (char c : word.toCharArray()) {
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }

        // Check if removing one character can make all frequencies equal
        for (int i = 0; i < word.length(); i++) {
            char removedChar = word.charAt(i);
            Map<Character, Integer> newFrequencyMap = new HashMap<>(frequencyMap);

            // Remove the current character from the frequency map
            newFrequencyMap.put(removedChar, newFrequencyMap.get(removedChar) - 1);
            if (newFrequencyMap.get(removedChar) == 0) {
                newFrequencyMap.remove(removedChar);
            }

            // Check if all frequencies are equal in the new frequency map
            int expectedFrequency = -1;
            for (int freq : newFrequencyMap.values()) {
                if (expectedFrequency == -1) {
                    expectedFrequency = freq;
                } else if (freq != expectedFrequency) {
                    break;
                }
            }

            // If all frequencies are equal, return true
            if (expectedFrequency != -1 && newFrequencyMap.size() > 0) {
                boolean allEqual = true;
                for (int freq : newFrequencyMap.values()) {
                    if (freq != expectedFrequency) {
                        allEqual = false;
                        break;
                    }
                }
                if (allEqual) {
                    return true;
                }
            }
        }

        // If no character can be removed to make all frequencies equal, return false
        return false;
    }
}

