public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        Arrays.sort(meetings, (a, b) -> a[0] - b[0]);

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] == b[1] ? a[0] - b[0] : a[1] - b[1]);

        int[] roomCount = new int[n];
        for (int i = 0; i < n && i < meetings.length; i++) {
            pq.offer(new int[]{i, meetings[i][1]});
            roomCount[i]++;
        }

        int idx = n;
        while (idx < meetings.length) {
            int[] earliestRoom = pq.poll();
            if (earliestRoom[1] <= meetings[idx][0]) {
                // No delay needed
                earliestRoom[1] = meetings[idx][1];
                pq.offer(earliestRoom);
                roomCount[earliestRoom[0]]++;
                idx++;
            } else {
                // Calculate the delay and adjust the meeting start time
                int originalDuration = meetings[idx][1] - meetings[idx][0];

                // Update the end time of the room with the delayed meeting duration
                earliestRoom[1] = Math.max(earliestRoom[1], meetings[idx][0]) + originalDuration;
                pq.offer(earliestRoom);
                roomCount[earliestRoom[0]]++;
            }
        }

        int maxMeetings = 0, result = 0;
        for (int i = 0; i < n; i++) {
            if (roomCount[i] > maxMeetings) {
                maxMeetings = roomCount[i];
                result = i;
            } else if (roomCount[i] == maxMeetings && i < result) {
                result = i;
            }
        }

        return result;
    }
}

