public class Solution {
    public long minimumMoney(int[][] transactions) {
        // Calculate the maximum cost among all transactions
        int maxCost = 0;

        for (int[] transaction : transactions) {
            maxCost = Math.max(maxCost, transaction[0]);
        }

        // Initialize minMoney with maxCost and calculate the net change for each transaction
        long minMoney = maxCost;
        long currentBalance = 0;

        int[] netChanges = new int[transactions.length];

        for (int i = 0; i < transactions.length; i++) {
            netChanges[i] = transactions[i][1] - transactions[i][0];
        }

        Arrays.sort(netChanges);

        // Iterate through the sorted net changes to find the minimum required money
        for (int i = 0; i < netChanges.length; i++) {
            currentBalance += netChanges[i];

            if (currentBalance < 0) {
                minMoney = Math.max(minMoney, -currentBalance + maxCost);
            }
        }

        return minMoney;
    }
