public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int countPalindromes(String s) {
        int n = s.length();

        // Initialize a 2D array to store counts of palindromic subsequences
        long[][] dp = new long[n][n];

        // Initialize single-character subsequences
        for (int i = 0; i < n; i++) {
            dp[i][i] = 1;
        }

        // Calculate counts for substrings of length 2 to n
        for (int length = 2; length <= n; length++) {
            for (int left = 0; left <= n - length; left++) {
                int right = left + length - 1;

                if (s.charAt(left) == s.charAt(right)) {
                    // If the first and last characters are equal, consider all possible splits
                    dp[left][right] += dp[left + 1][right - 1];
                    dp[left][right] %= MOD;

                    // Add counts for single-character subsequences at the start and end
                    if (length > 2) {
                        for (int k = left + 1; k < right; k++) {
                            dp[left][right] += dp[left + 1][k] * dp[k + 1][right - 1];
                            dp[left][right] %= MOD;
                        }
                    } else {
                        // For substrings of length 2, add the count for the single-character subsequence
                        dp[left][right] += 2; // Changed from 1 to 2
                        dp[left][right] %= MOD;
                    }
                } else {
                    // If the first and last characters are different, consider all possible splits
                    for (int k = left + 1; k < right; k++) {
                        dp[left][right] += dp[left + 1][k] * dp[k + 1][right];
                        dp[left][right] %= MOD;
                    }
                }
            }
        }

        // Return the count of palindromic subsequences for the entire string
        return (int) dp[0][n - 1];
    }
}

