public class Solution {
    public String[] splitMessage(String message, int limit) {
        int n = message.length();
        for (int k = 1; k <= n; k++) {
            if (n + Math.max(Integer.toString(k).length(), Integer.toString(n).length()) * 2 + 3 > limit * k) continue;
            boolean ok = true;
            String[] res = new String[k];
            int j = 0;
            for (int i = 0; i < k; i++) {
                // Calculate the maximum possible length for a part without considering the suffix
                int maxPartLength = limit - Math.max(Integer.toString(i + 1).length(), Integer.toString(k).length()) * 2 - 3;

                // Adjust the part length based on whether it's the last part or not
                int partLength;
                if (i == k - 1) {
                    partLength = n - j;
                } else {
                    partLength = Math.min(maxPartLength, n - j);
                }

                if (j + partLength > n || partLength < 0) {
                    ok = false;
                    break;
                }
                res[i] = message.substring(j, j + partLength) + "<" + (i + 1) + "/" + k + ">";
                j += partLength;
            }
            if (!ok || n != j) continue;
            return res;
        }
        return new String[0];
    }
}

