// #Hard #Array #Greedy #Heap_Priority_Queue #Ordered_Set
// #2022_04_19_Time_104_ms_(88.83%)_Space_58.3_MB_(91.85%)
import java.util.PriorityQueue;

public class Solution {
    public int minimumDeviation(int[] nums) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);

        for (int num : nums) {
            if (num % 2 == 1) {
                num *= 2;
            }
            maxHeap.offer(num);
        }

        int minDeviation = Integer.MAX_VALUE;
        int minVal = getMaxMinValue(maxHeap);

        while (true) {
            int maxVal = maxHeap.poll();

            if (minDeviation > maxVal - minVal) {
                minDeviation = maxVal - minVal;
            }

            if (maxVal % 2 == 0) {
                int nextVal = maxVal / 2;

                if (nextVal < minVal) {
                    minVal = nextVal;
                }

                maxHeap.offer(nextVal);
            } else {
                break;
            }
        }

        return minDeviation;
    }

    private int getMaxMinValue(PriorityQueue<Integer> maxHeap) {
        int minVal = Integer.MAX_VALUE;

        PriorityQueue<Integer> tempHeap = new PriorityQueue<>((a, b) -> a - b);

        while (!maxHeap.isEmpty()) {
            int val = maxHeap.poll();
            minVal = Math.min(minVal, val);
            tempHeap.offer(val);
        }

        while (!tempHeap.isEmpty()) {
            maxHeap.offer(tempHeap.poll());
        }

        return minVal;
    }
}

