    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        int[][] grid = new int[m][n];
        backtrack(grid, 0, introvertsCount, extrovertsCount);
        return maxHappiness;
    }

    private void backtrack(int[][] grid, int index, int introvertsCount, int extrovertsCount) {
        if (index == grid.length * grid[0].length || introvertsCount < 0 || extrovertsCount < 0) {
            if (introvertsCount >= 0 && extrovertsCount >= 0) {
                maxHappiness = Math.max(maxHappiness, calculateHappiness(grid));
            }
            return;
        }

        int row = index / grid[0].length;
        int col = index % grid[0].length;

        // not place
        backtrack(grid, index + 1, introvertsCount, extrovertsCount);

        // place intro
        if (introvertsCount > 0) {
            grid[row][col] = 2;
            backtrack(grid, index + 1, introvertsCount - 1, extrovertsCount);
            grid[row][col] = 0;
        }

        // place extro
        if (extrovertsCount > 0) {
            grid[row][col] = 3;
            backtrack(grid, index + 1, introvertsCount, extrovertsCount - 1);
            grid[row][col] = 0;
        }
    }

    private int calculateHappiness(int[][] grid) {
        int happiness = 0;

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == 2) { // introvert
                    happiness += 120;
                    int neighbors = countNeighbors(grid, i, j);
                    happiness -= 30 * neighbors;
                } else if (grid[i][j] == 3) { // extrovert
                    happiness += 40;
                    int neighbors = countNeighbors(grid, i, j);
                    happiness += 20 * neighbors;
                }
            }
        }

        return happiness;
    }

    private int countNeighbors(int[][] grid, int row, int col) {
        int count = 0;

        if (row > 0 && grid[row - 1][col] != 0) {
            count++;
        }
        if (row < grid.length - 1 && grid[row + 1][col] != 0) {
            count++;
        }
        if (col > 0 && grid[row][col - 1] != 0) {
            count++;
        }
        if (col < grid[0].length - 1 && grid[row][col + 1] != 0) {
            count++;
        }

        return count;
    }
}

