import java.util.*;

public class Solution {
    private long minCost = Long.MAX_VALUE;

    public long minimumTotalCost(int[] nums1, int[] nums2) {
        boolean[] swapped = new boolean[nums1.length];
        backtrack(nums1, nums2, 0, 0, swapped);

        return minCost == Long.MAX_VALUE ? -1 : minCost;
    }

    private void backtrack(int[] nums1, int[] nums2, long cost, int index, boolean[] swapped) {
        if (index >= nums1.length) {
            if (isValid(nums1, nums2)) {
                minCost = Math.min(minCost, cost);
            }
            return;
        }

        // Try not swapping
        backtrack(nums1, nums2, cost, index + 1, swapped);

        for (int j = 0; j < nums1.length; j++) {
            if (!swapped[j] && nums1[index] != nums2[j]) {
                swap(nums1, index, j);
                swapped[index] = true;
                swapped[j] = true;

                backtrack(nums1, nums2, cost + index + j, index + 1, swapped);

                swap(nums1, index, j);
                swapped[index] = false;
                swapped[j] = false;
            }
        }
    }

    private boolean isValid(int[] nums1, int[] nums2) {
        for (int i = 0; i < nums1.length; i++) {
            if (nums1[i] == nums2[i]) {
                return false;
            }
        }

        return true;
    }

    private void swap(int[] nums1, int i, int j) {
        int temp = nums1[i];
        nums1[i] = nums1[j];
        nums1[j] = temp;
    }
}

