import java.util.*;

public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int num : nums) {
            count.put(num, count.getOrDefault(num, 0) + 1);
        }

        List<int[]> list = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : count.entrySet()) {
            list.add(new int[] {entry.getKey(), entry.getValue()});
        }

        Arrays.sort(quantity);
        reverseArray(quantity);

        return dfs(list, quantity, 0);
    }

    private boolean dfs(List<int[]> list, int[] quantity, int index) {
        if (index == quantity.length) {
            return true;
        }

        for (int i = 0; i < list.size(); i++) {
            if (list.get(i)[1] >= quantity[index]) {
                list.get(i)[1] -= quantity[index];
                if (dfs(list, quantity, index + 1)) {
                    return true;
                }
                list.get(i)[1] += quantity[index];
            }
        }

        return false;
    }

    private void reverseArray(int[] array) {
        int left = 0;
        int right = array.length - 1;
        while (left < right) {
            int temp = array[left];
            array[left] = array[right];
            array[right] = temp;
            left++;
            right--;
        }
    }
}

