import java.util.*;

public class Solution {
    private int result = Integer.MAX_VALUE;

    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) return -1;

        // Check for more than k occurrences of any single element
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
            if (countMap.get(num) > k) return -1;
        }

        Arrays.sort(nums);
        int subsetSize = n / k;

        // Distribute elements into subsets ensuring no duplicates within a subset
        List<List<Integer>> subsets = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            subsets.add(new ArrayList<>());
        }

        backtrack(subsets, nums, 0, subsetSize);

        return result == Integer.MAX_VALUE ? -1 : result;
    }

    private void backtrack(List<List<Integer>> subsets, int[] nums, int index, int subsetSize) {
        if (index == nums.length) {
            int sumOfIncompatibilities = calculateSum(subsets, subsetSize);
            result = Math.min(result, sumOfIncompatibilities);
            return;
        }

        for (int i = 0; i < subsets.size(); i++) {
            if (subsets.get(i).size() == subsetSize) continue;

            boolean containsNum = false;
            for (Integer num : subsets.get(i)) {
                if (num == nums[index]) {
                    containsNum = true;
                    break;
                }
            }

            if (!containsNum) {
                subsets.get(i).add(nums[index]);
                backtrack(subsets, nums, index + 1, subsetSize);
                subsets.get(i).remove(subsets.get(i).size() - 1);
            }
        }
    }

    private int calculateSum(List<List<Integer>> subsets, int subsetSize) {
        int sumOfIncompatibilities = 0;
        for (List<Integer> subset : subsets) {
            Collections.sort(subset);
            if (subset.size() != subsetSize) return Integer.MAX_VALUE; // Invalid subset size
            sumOfIncompatibilities += subset.get(subsetSize - 1) - subset.get(0);
        }

        return sumOfIncompatibilities;
    }
}

