public class Solution {
    private int maxBoxes;
    private int maxWeight;

    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        this.maxBoxes = maxBoxes;
        this.maxWeight = maxWeight;

        int n = boxes.length;
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + boxes[i][1];
        }

        // dp[i][j] represents the minimum number of trips to deliver boxes from i to j
        int[][] dp = new int[n + 1][n + 1];
        for (int len = 1; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                // calculate the number of trips if we deliver boxes from i to j in one trip
                dp[i][j] = getTrips(boxes, i, j);
                for (int k = i; k < j; k++) {
                    dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j]);
                }
            }
        }

        return dp[0][n - 1];
    }

    private int getTrips(int[][] boxes, int start, int end) {
        if (end < start) return 0;

        // Check capacity constraints
        int weight = 0;
        for (int i = start; i <= end; i++) {
            weight += boxes[i][1];
        }
        if (weight > maxWeight || end - start + 1 > maxBoxes) {
            return Integer.MAX_VALUE;
        }

        // Calculate trips based on port changes
        int trips = 2; // initial trip to storage and back
        for (int i = start; i <= end; i++) {
            if (i == start || boxes[i][0] != boxes[i - 1][0]) {
                trips++;
            }
        }
        return trips;
    }
}

