public class Solution {
    public int createSortedArray(int[] instructions) {
        final int MOD = (int) 1e9 + 7;
        TreeSet<Integer> set = new TreeSet<>();
        long cost = 0;

        for (int num : instructions) {
            int leftCount = set.headSet(num).size();

            // Calculate rightCount considering elements strictly greater than num
            int rightCount = set.tailSet(num).size();
            if (set.contains(num)) {
                // Adjust rightCount if num is already in the set
                rightCount--;
            }

            cost += Math.min(leftCount, rightCount);
            cost %= MOD;
            set.add(num);
        }

        return (int) cost;
    }
}

