import java.util.*;

public class Solution {
    public int[] frequencySort(int[] nums) {
        Map<Integer, Integer> frequencyMap = new HashMap<>();

        // Count the frequency of each number
        for (int num : nums) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }

        // Sort the numbers based on their frequency and value
        List<Integer> sortedList = new ArrayList<>(frequencyMap.keySet());
        Collections.sort(sortedList, (a, b) -> {
            int freqA = frequencyMap.get(a);
            int freqB = frequencyMap.get(b);

            if (freqA == freqB) {
                return b - a; // Decreasing order for same frequency
            } else {
                return freqA - freqB; // Increasing order by frequency
            }
        });

        // Create the result array
        int[] result = new int[nums.length];
        int index = 0;
        for (int num : sortedList) {
            int freq = frequencyMap.get(num);
            while (freq-- > 0) {
                result[index++] = num;
            }
        }

        return result;
    }
}

