// #Hard #Array #Math #Union_Find #2022_04_18_Time_7_ms_(98.45%)_Space_75.7_MB_(97.93%)
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Boolean> areConnected(int n, int threshold, int[][] queries) {
        UnionFind uf = new UnionFind(n + 1);

        // Connect cities that share a common divisor greater than the threshold
        for (int z = threshold + 1; z <= n; z++) {
            for (int x = z; x <= n; x += z) {
                for (int y = x + z; y <= n; y += z) {
                    uf.union(x, y);
                }
            }
        }

        List<Boolean> result = new ArrayList<>();

        // Check if each pair of cities is connected
        for (int[] query : queries) {
            int city1 = query[0];
            int city2 = query[1];
            result.add(uf.isConnected(city1, city2));
        }

        return result;
    }

    private static class UnionFind {
        private final int[] parent;

        public UnionFind(int size) {
            this.parent = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                parent[rootX] = rootY;
            }
        }

        public boolean isConnected(int x, int y) {
            return find(x) == find(y);
        }

        private int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }
    }
}

