        for (int[] edge : edges) {
            graph[edge[0] - 1].add(edge[1] - 1);
            graph[edge[1] - 1].add(edge[0] - 1);
        }

        int[] result = new int[n - 1];

        // Iterate over all possible subsets of nodes
        for (int mask = 1; mask < (1 << n); mask++) {
            List<Integer> subset = new ArrayList<>();

            // Get the nodes in the current subset
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    subset.add(i);
                }
            }

            // Check if the subset is connected
            if (!isConnected(graph, subset)) {
                continue;
            }

            int maxDistance = getMaxDistance(graph, subset);

            // Update the result array
            if (maxDistance > 0 && maxDistance < n) {
                result[maxDistance - 1]++;
            }
        }

        return result;
    }

    private boolean isConnected(List<Integer>[] graph, List<Integer> subset) {
        int start = subset.get(0);
        boolean[] visited = new boolean[graph.length];

        // Perform DFS from the first node in the subset
        dfs(graph, start, visited, subset);

        // Check if all nodes in the subset are visited
        for (int node : subset) {
            if (!visited[node]) {
                return false;
            }
        }

        return true;
    }

    private void dfs(List<Integer>[] graph, int node, boolean[] visited, List<Integer> subset) {
        visited[node] = true;

        // Visit all neighbors of the current node that are in the subset
        for (int neighbor : graph[node]) {
            if (!visited[neighbor] && subset.contains(neighbor)) {
                dfs(graph, neighbor, visited, subset);
            }
        }
    }

    private int getMaxDistance(List<Integer>[] graph, List<Integer> subset) {
        int maxDistance = 0;

        // Calculate the maximum distance between any two nodes in the subset
        for (int i = 0; i < subset.size(); i++) {
            for (int j = i + 1; j < subset.size(); j++) {
                int distance = getDistance(graph, subset.get(i), subset.get(j));
                maxDistance = Math.max(maxDistance, distance);
            }
        }

        return maxDistance;
    }

    private int getDistance(List<Integer>[] graph, int start, int end) {
        boolean[] visited = new boolean[graph.length];

        // Perform BFS from the start node to find the shortest path to the end node
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[] {start, 0});
        visited[start] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();

            if (current[0] == end) {
                return current[1];
            }

            // Visit all neighbors of the current node
            for (int neighbor : graph[current[0]]) {
                if (!visited[neighbor]) {
                    queue.offer(new int[] {neighbor, current[1] + 1});
                    visited[neighbor] = true;
                }
            }
        }

        return -1; // No path found
    }
}

