// #Hard #Array #Dynamic_Programming #Math #Combinatorics
public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int n = destination[0];
        int m = destination[1];

        // Calculate the total number of paths
        long totalPaths = combination(n + m, n);

        // Check if k is valid
        if (k < 1 || k > totalPaths) {
            return "";
        }

        StringBuilder path = new StringBuilder();
        int remainingDown = n;
        int remainingRight = m;

        for (int i = 0; i < n + m; i++) {
            // Calculate the number of paths that start with 'H' at this position
            long rightPaths = combination(remainingDown + remainingRight - 1, remainingDown);

            if (k <= rightPaths) {
                path.append('H');
                remainingRight--;
            } else {
                path.append('V');
                k -= rightPaths;
                remainingDown--;
            }
        }

        return path.toString();
    }

    // Function to calculate the combination of two numbers
    private long combination(int n, int r) {
        if (r > n - r) {
            r = n - r;
        }

        long result = 1;

        for (int i = 0; i < r; i++) {
            result = result * (n - i) / (i + 1);
        }

        return result;
    }
}

