// #Medium #Array #Math #Prefix_Sum #2022_04_18_Time_4_ms_(80.17%)_Space_58.3_MB_(88.84%)
public class Solution {
    public int[] getSumAbsoluteDifferences(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];

        // Calculate the total sum of all elements in the array
        long totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        // Initialize variables to store the prefix sum and suffix sum
        long prefixSum = 0;

        // Iterate through the array to calculate result[i]
        for (int i = 0; i < n; i++) {
            // Calculate the suffix sum
            long suffixSum = totalSum - prefixSum - nums[i];

            // Calculate the number of elements less than and greater than nums[i]
            int leftCount = i;
            int rightCount = n - i - 1;

            // Calculate result[i] using the formula: 
            // (nums[i] * leftCount) - prefixSum + suffixSum - (nums[i] * rightCount)
            long diff = (long) nums[i] * leftCount - prefixSum + suffixSum - (long) nums[i] * rightCount;

            result[i] = Math.abs((int) diff);

            // Update the prefix sum
            prefixSum += nums[i];
        }

        return result;
    }
}

