public class Solution {
    public int[][] matrixRankTransform(int[][] matrix) {
        if (matrix.length == 0 || matrix[0].length == 0) return new int[0][0];

        int m = matrix.length, n = matrix[0].length;
        int[][] ans = new int[m][n];
        Map<Integer, List<int[]>> map = new HashMap<>();

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (!map.containsKey(matrix[i][j])) {
                    map.put(matrix[i][j], new ArrayList<>());
                }
                map.get(matrix[i][j]).add(new int[] {i, j});
            }
        }

        List<Integer> sortedValues = new ArrayList<>(map.keySet());
        Collections.sort(sortedValues);

        Map<String, Integer> rowRanks = new HashMap<>();
        Map<String, Integer> colRanks = new HashMap<>();

        for (int val : sortedValues) {
            List<int[]> list = map.get(val);
            int maxRank = 0;

            // Calculate the maximum rank
            for (int[] pos : list) {
                int rowRank = rowRanks.getOrDefault("row_" + pos[0], 0);
                int colRank = colRanks.getOrDefault("col_" + pos[1], 0);

                maxRank = Math.max(maxRank, Math.max(rowRank, colRank));
            }

            // Update the ranks
            for (int[] pos : list) {
                ans[pos[0]][pos[1]] = maxRank + 1;
                rowRanks.put("row_" + pos[0], maxRank + 1);
                colRanks.put("col_" + pos[1], maxRank + 1);
            }
        }

        return ans;
    }
}

