import java.util.*;

public class Solution {
    public int minDeletions(String s) {
        Map<Character, Integer> frequencyMap = new HashMap<>();

        // Count the frequency of each character
        for (char c : s.toCharArray()) {
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }

        Set<Integer> uniqueFrequencies = new HashSet<>();
        int deletions = 0;

        // Sort frequencies in descending order
        List<Integer> sortedFrequencies = new ArrayList<>(frequencyMap.values());
        Collections.sort(sortedFrequencies, (a, b) -> b - a);

        for (int freq : sortedFrequencies) {
            while (uniqueFrequencies.contains(freq)) {
                if (freq == 0) break;
                deletions++;
                freq--;
            }
            uniqueFrequencies.add(freq);
        }

        return deletions;
    }
}

