// #Medium #Array #Dynamic_Programming #Heap_Priority_Queue #Sliding_Window #Queue #Monotonic_Queue
// #2022_04_13_Time_23_ms_(86.05%)_Space_56.4_MB_(95.27%)
import java.util.Deque;
import java.util.LinkedList;

public class Solution {
    public int maxResult(int[] nums, int k) {
        int n = nums.length;
        int[] dp = new int[n];
        Deque<Integer> dq = new LinkedList<>();

        for (int i = 0; i < n; i++) {
            // Remove elements that are out of the window
            while (!dq.isEmpty() && dq.peekFirst() < i - k) {
                dq.pollFirst();
            }

            // If this is not the first element, calculate dp[i]
            if (i > 0) {
                dp[i] = nums[i];
                if (!dq.isEmpty()) {
                    dp[i] += dp[dq.peekFirst()];
                }
            } else {
                dp[i] = nums[i];
            }

            // Remove elements that have smaller values than the current element
            while (!dq.isEmpty() && dp[dq.peekLast()] < dp[i]) {
                dq.pollLast();
            }

            // Add the current index to the deque
            dq.offerLast(i);
        }

        return dp[n - 1];
    }
}

