import java.util.HashSet;
import java.util.PriorityQueue;

public class Solution {
    public String findLexSmallestString(String s, int a, int b) {
        HashSet<String> visited = new HashSet<>();
        PriorityQueue<String> pq = new PriorityQueue<>();

        pq.offer(s);
        visited.add(s);

        while (!pq.isEmpty()) {
            String curr = pq.poll();

            if (isSmaller(curr, s)) {
                s = curr;
            }

            // Add a to all odd indices of s
            StringBuilder sb1 = new StringBuilder();
            for (int i = 0; i < curr.length(); i++) {
                int num = (curr.charAt(i) - '0') + (i % 2 == 1 ? a : 0);
                if (num > 9) {
                    num %= 10;
                }
                sb1.append(num);
            }

            String next1 = sb1.toString();
            if (!visited.contains(next1)) {
                pq.offer(next1);
                visited.add(next1);
            }

            // Rotate s to the right by b positions
            StringBuilder sb2 = new StringBuilder(curr.substring(curr.length() - b));
            sb2.append(curr.substring(0, curr.length() - b));

            String next2 = sb2.toString();
            if (!visited.contains(next2)) {
                pq.offer(next2);
                visited.add(next2);
            }
        }

        return s;
    }

    private boolean isSmaller(String a, String b) {
        for (int i = 0; i < a.length(); i++) {
            if (a.charAt(i) != b.charAt(i)) {
                return a.charAt(i) - '0' < b.charAt(i) - '0';
            }
        }

        return false;
    }
}

