// #2022_04_12_Time_122_ms_(97.44%)_Space_86.3_MB_(94.58%)
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        int n = points.size();
        int sameLocation = 0;
        List<Double> angles = new ArrayList<>();

        for (List<Integer> point : points) {
            if (point.get(0).equals(location.get(0)) && point.get(1).equals(location.get(1))) {
                sameLocation++;
            } else {
                double angleTemp = Math.atan2(point.get(1) - location.get(1), point.get(0) - location.get(0));
                if (angleTemp < 0) {
                    angleTemp += 2 * Math.PI;
                }
                angles.add(angleTemp);
            }
        }

        Collections.sort(angles);

        int maxPoints = sameLocation;
        int i = 0, j = 0;
        while (i < angles.size()) {
            double diff = angles.get(i) - angles.get(j);
            if (diff > angle * Math.PI / 180 || diff < -angle * Math.PI / 180) {
                j++;
            } else {
                maxPoints = Math.max(maxPoints, i - j + 1 + sameLocation);
                i++;
            }
        }

        return maxPoints;
    }
}

