// #Hard #Array #String #Dynamic_Programming #2022_04_20_Time_50_ms_(95.33%)_Space_75.1_MB_(48.00%)
public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numWays(String[] words, String target) {
        // Check if the target string contains only lowercase letters
        for (char c : target.toCharArray()) {
            if (c < 'a' || c > 'z') {
                throw new IllegalArgumentException("Target string should contain only lowercase letters");
            }
        }

        int[][] count = new int[26][words[0].length()];

        // Count the frequency of each character at each position
        for (String word : words) {
            for (int i = 0; i < word.length(); i++) {
                count[word.charAt(i) - 'a'][i]++;
            }
        }

        int[][] dp = new int[target.length() + 1][words[0].length() + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= target.length(); i++) {
            for (int j = 0; j < words[0].length(); j++) {
                if (i == 1) { 
                    int k = target.charAt(i - 1) - 'a';
                    if (count[k][j] > 0) {
                        dp[i][j + 1] = (dp[i][j + 1] + count[k][j]) % MOD;
                    }
                } else { 
                    int k = target.charAt(i - 1) - 'a';
                    for (int prevJ = 0; prevJ <= j; prevJ++) {
                        if (count[k][prevJ] > 0) {
                            dp[i][j + 1] = (dp[i][j + 1] + (int)((long)dp[i - 1][prevJ] * count[k][prevJ] % MOD)) % MOD;
                        }
                    }
                }
            }
        }

        int result = 0;
        for (int i = 0; i <= words[0].length(); i++) {
            result = (result + dp[target.length()][i]) % MOD;
        }

        return result;
    }
}

