public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int concatenatedBinary(int n) {
        long result = 0;
        int length = 0;

        for (int i = 1; i <= n; i++) {
            // calculate the number of bits in the current integer
            if ((i & (i - 1)) == 0) {
                length++;
            }

            // shift the result to the left by the number of bits in the current integer
            result = ((result << (length)) | i) % MOD;
        }

        return (int) result;
    }
}

