public class Solution {
    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        Set<Integer> set = new HashSet<>();
        for (int num : forbidden) {
            set.add(num);
        }

        Queue<Pair> queue = new LinkedList<>();
        boolean[] visited = new boolean[2001];
        queue.offer(new Pair(0, false));
        visited[0] = true;
        int step = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                Pair pair = queue.poll();
                if (pair.i == x) return step;

                // jump forward
                int nextForward = pair.i + a;
                if (nextForward <= 2000 && !set.contains(nextForward) && !visited[nextForward]) {
                    visited[nextForward] = true;
                    queue.offer(new Pair(nextForward, false));
                }

                // jump backward
                if (!pair.b) {
                    int nextBackward = pair.i - b;
                    if (nextBackward >= 0 && !set.contains(nextBackward) && !visited[nextBackward]) {
                        visited[nextBackward] = true;
                        queue.offer(new Pair(nextBackward, true));
                    }
                }
            }
            step++;
        }

        return -1;
    }

    public static class Pair {
        int i;
        boolean b;

        public Pair(int i, boolean b) {
            this.i = i;
            this.b = b;
        }
    }
}

