        ListNode preStart = list1;
        for (int i = 0; i < a - 1; i++) {
            preStart = preStart.next;
        }

        // Find the node after the end of the section to be removed
        ListNode postEnd = list1;
        for (int i = 0; i <= b; i++) {
            postEnd = postEnd.next;
        }

        // Find the last node of list2
        ListNode lastNodeOfList2 = list2;
        while (lastNodeOfList2.next != null) {
            lastNodeOfList2 = lastNodeOfList2.next;
        }

        // Remove the section from list1 and connect it with list2
        preStart.next = list2;
        lastNodeOfList2.next = postEnd;

        return list1;
    }
