        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        // Create a priority queue to store cells in the form (effort, row, col)
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);

        // Add the starting cell with effort 0
        pq.offer(new int[] {0, 0, 0});

        // Create a visited set to keep track of visited cells
        boolean[][] visited = new boolean[rows][cols];

        while (!pq.isEmpty()) {
            int[] current = pq.poll();
            int effort = current[0];
            int row = current[1];
            int col = current[2];

            // If this is the destination cell, return the effort
            if (row == rows - 1 && col == cols - 1) {
                return effort;
            }

            // Mark the current cell as visited
            visited[row][col] = true;

            // Explore neighbors
            for (int[] direction : directions) {
                int newRow = row + direction[0];
                int newCol = col + direction[1];

                // Check if the neighbor is within bounds and not visited
                if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && !visited[newRow][newCol]) {
                    // Calculate the effort to reach the neighbor
                    int newEffort = Math.max(effort, Math.abs(heights[row][col] - heights[newRow][newCol]));

                    // Add the neighbor to the priority queue
                    pq.offer(new int[] {newEffort, newRow, newCol});
                }
            }
        }

        // If there's no path to the destination, return -1 (this should not happen)
        return -1;
    }
}

