public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfSets(int n, int k) {
        long[][] dp = new long[n + 1][k + 1];

        // Base case: there is one way to draw zero segments
        for (int i = 0; i <= n; i++) {
            dp[i][0] = 1;
        }

        // Fill up the DP table in a bottom-up manner
        for (int i = 2; i <= n; i++) {
            for (int j = 1; j <= k && j <= i / 2; j++) {
                // For each possible segment end point, calculate the number of ways to draw j segments
                for (int end = 2; end <= i; end++) {
                    int length = end;
                    if (length >= 2) {
                        dp[i][j] = (dp[i][j] + dp[i - length][j - 1]) % MOD;
                    }
                }
            }
        }

        // The answer is stored in dp[n][k]
        return (int) dp[n][k];
    }
}

