import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    // Helper method to check if anyone in the queue prefers a certain type
    private boolean containsPreference(Queue<Integer> queue, int preference) {
        for (Integer pref : queue) {
            if (pref == preference) return true;
        }
        return false;
    }

    public int countStudents(int[] students, int[] sandwiches) {
        Queue<Integer> studentQueue = new LinkedList<>();

        // Initialize the queue with student preferences
        for (int preference : students) {
            studentQueue.offer(preference);
        }

        // Iterate over the sandwiches
        for (int sandwichType : sandwiches) {
            boolean foundMatch = false;

            // Check if there are any students who prefer this type of sandwich
            while (!studentQueue.isEmpty() && !foundMatch) {
                // If the student at the front prefers this type, serve them and remove from queue
                if (studentQueue.peek() == sandwichType) {
                    studentQueue.poll();
                    foundMatch = true;
                } else {
                    // Move the student to the end of the queue if they don't prefer this type
                    int preference = studentQueue.poll();
                    studentQueue.offer(preference);

                    // If after moving a student, no one in the queue prefers this type, break
                    if (!containsPreference(studentQueue, sandwichType)) {
                        break;
                    }
                }
            }

            // If no match is found for any remaining students and we've checked all of them, break the loop
            if (studentQueue.isEmpty() || !foundMatch) {
                break;
            }
        }

        // The number of students who are unable to eat is the size of the queue
        return studentQueue.size();
    }
}

