import java.util.PriorityQueue;

public class Solution {
    public int furthestBuilding(int[] heights, int bricks, int ladders) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();

        for (int i = 0; i < heights.length - 1; i++) {
            int diff = heights[i + 1] - heights[i];

            if (diff > 0) {
                // Add the difference to the priority queue
                pq.offer(diff);

                // If the size of the priority queue exceeds the number of ladders,
                // remove the smallest element from the queue and subtract it from bricks
                if (pq.size() > ladders) {
                    bricks -= pq.poll();

                    // If bricks becomes negative, return i as we cannot move further
                    if (bricks < 0) {
                        return i;
                    }
                }
            }
        }

        // If we can reach the end of the array without using up all bricks and ladders,
        // return the last index
        return heights.length - 1;
    }
}

