// #Hard #Array #Greedy #Heap_Priority_Queue #Ordered_Set
// #2022_04_11_Time_118_ms_(98.21%)_Space_61.4_MB_(84.23%)
public class Solution {
    public List<Integer> busiestServers(int k, int[] arrival, int[] load) {
        PriorityQueue<int[]> busy = new PriorityQueue<>((a, b) -> a[1] - b[1]);
        TreeSet<Integer> available = new TreeSet<>();
        for (int i = 0; i < k; i++) {
            available.add(i);
        }

        int[] requestCount = new int[k];
        for (int i = 0, n = arrival.length; i < n; i++) {
            while (!busy.isEmpty() && busy.peek()[1] <= arrival[i]) {
                available.add(busy.poll()[0]);
            }

            if (available.isEmpty()) continue;

            Integer next = available.ceiling(i % k);
            if (next == null) next = available.first();

            requestCount[next]++;
            busy.offer(new int[] {next, arrival[i] + load[i]});
            available.remove(next);
        }

        int maxRequestCount = 0;
        for (int count : requestCount) {
            maxRequestCount = Math.max(maxRequestCount, count);
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (requestCount[i] == maxRequestCount) {
                result.add(i);
            }
        }

        return result;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        int k = 3;
        int[] arrival = {1,2,3,4,5};
        int[] load = {5,2,3,1,2};
        System.out.println(solution.busiestServers(k, arrival, load));
    }
}

