public class Solution {
    public int stoneGameVII(int[] stones) {
        int n = stones.length;

        // Calculate prefix sum for efficient calculation of remaining stones' values
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + stones[i];
        }

        // Initialize a 2D array to store the maximum difference in scores for subproblems
        int[][] dp = new int[n][n];

        // Fill up the dp table using dynamic programming
        for (int length = 1; length <= n; length++) {
            for (int i = 0; i < n - length + 1; i++) {
                int j = i + length - 1;
                if (length == 1) {
                    // Base case: only one stone left
                    dp[i][j] = stones[i];
                } else {
                    // Calculate the maximum difference in scores for the current subproblem
                    int maxDiff = Integer.MIN_VALUE;
                    // Try removing the leftmost stone
                    int leftScore = prefixSum[j + 1] - prefixSum[i + 1] - (i + 1 <= j ? dp[i + 1][j] : 0);
                    // Try removing the rightmost stone
                    int rightScore = prefixSum[j] - prefixSum[i] - (i <= j - 1 ? dp[i][j - 1] : 0);
                    maxDiff = Math.max(leftScore, rightScore);
                    dp[i][j] = maxDiff;
                }
            }
        }

        // The final answer should be the maximum difference in scores between Alice and Bob
        return dp[0][n - 1];
    }
}

