import java.util.Arrays;

public class Solution {
    public int minimumEffort(int[][] tasks) {
        // Sort the tasks based on the difference between actual and minimum energy
        Arrays.sort(tasks, (a, b) -> (b[1] - b[0]) - (a[1] - a[0]));

        int totalEnergy = 0;
        int currentEnergy = 0;

        for (int[] task : tasks) {
            // If the current energy is not enough to start the task, update it
            if (currentEnergy < task[1]) {
                totalEnergy += task[1] - currentEnergy;
                currentEnergy = task[1];
            }

            // Finish the task and update the current energy
            currentEnergy -= task[0];
        }

        return totalEnergy;
    }
}

