public class Solution {
    public int maximumRequests(int n, int[][] requests) {
        int maxRequests = 0;

        for (int mask = 1; mask < (1 << requests.length); mask++) {
            int[] delta = new int[n];

            for (int i = 0; i < requests.length; i++) {
                if ((mask & (1 << i)) != 0) {
                    delta[requests[i][0]]--;
                    delta[requests[i][1]]++;
                }
            }

            boolean isValid = true;
            for (int d : delta) {
                if (d != 0) {
                    isValid = false;
                    break;
                }
            }

            if (isValid) {
                maxRequests = Math.max(maxRequests, Integer.bitCount(mask));
            }
        }

        return maxRequests;
    }
}

