public class Solution {
    public int stoneGameVI(int[] aliceValues, int[] bobValues) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> (b[0] + b[1]) - (a[0] + a[1]));

        for (int i = 0; i < aliceValues.length; i++) {
            pq.offer(new int[] {aliceValues[i], bobValues[i]});
        }

        int aliceScore = 0, bobScore = 0;
        boolean isAliceTurn = true; // Flag to track whose turn it is

        while (!pq.isEmpty()) {
            if (isAliceTurn) {
                int[] stone = pq.poll();
                aliceScore += stone[0];
            } else {
                int[] stone = pq.poll();
                bobScore += stone[1];
            }
            isAliceTurn = !isAliceTurn; // Alternate turns
        }

        if (aliceScore > bobScore) return 1;
        else if (bobScore > aliceScore) return -1;
        else return 0;
    }
