import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    private DisjointSetUnion dsu;

    public boolean[] distanceLimitedPathsExist(int n, int[][] edgeList, int[][] queries) {
        // Sort the edges by their distances
        Arrays.sort(edgeList, Comparator.comparingInt(a -> a[2]));

        // Initialize the result array
        boolean[] answer = new boolean[queries.length];

        // Sort the queries by their limits
        Integer[] queryIndices = new Integer[queries.length];
        for (int i = 0; i < queries.length; i++) {
            queryIndices[i] = i;
        }
        Arrays.sort(queryIndices, Comparator.comparingInt(a -> queries[a][2]));

        int edgeIndex = 0;

        dsu = new DisjointSetUnion(n);

        // Process each query
        for (int queryIndex : queryIndices) {
            int p = queries[queryIndex][0];
            int q = queries[queryIndex][1];
            int limit = queries[queryIndex][2];

            while (edgeIndex < edgeList.length && edgeList[edgeIndex][2] < limit) {
                // Add the current edge to the DSU
                int u = edgeList[edgeIndex][0];
                int v = edgeList[edgeIndex][1];
                dsu.union(u, v);
                edgeIndex++;
            }

            answer[queryIndex] = dsu.find(p) == dsu.find(q);
        }

        return answer;
    }
}

class DisjointSetUnion {
    private int[] parent;
    private int[] rank;

    public DisjointSetUnion(int n) {
        // Initialize the DSU data structure
        parent = new int[n + 1];
        rank = new int[n + 1];

        for (int i = 0; i <= n; i++) {
            parent[i] = i;
        }
    }

    public int find(int num) {
        if (parent[num] != num) {
            parent[num] = find(parent[num]);
        }
        return parent[num];
    }

    public void union(int u, int v) {
        // Find the roots of u and v
        int rootU = find(u);
        int rootV = find(v);

        if (rootU != rootV) {
            if (rank[rootU] < rank[rootV]) {
                parent[rootU] = rootV;
            } else if (rank[rootU] > rank[rootV]) {
                parent[rootV] = rootU;
            } else {
                parent[rootV] = rootU;
                rank[rootU]++;
            }
        }
    }
}

