/**
 * This public class Solution a solution for calculating the number of matches played 
 * in a tournament until a winner is decided.
 */
public class Solution {
    /**
     * Calculate the total number of matches played in the tournament.
     * @param n The initial number of teams in the tournament.
     * @return The total number of matches played.
     */
    public int numberOfMatches(int n) {
        // Initialize the total number of matches to 0
        int totalMatches = 0;

        // Continue the tournament until only one team remains
        while (n > 1) {
            // If the current number of teams is even, each team gets paired with another team
            if (n % 2 == 0) {
                // Calculate the number of matches played in this round
                int matches = n / 2;
                // Update the total number of matches
                totalMatches += matches;
                // Update the number of teams for the next round
                n /= 2;
            } 
            // If the current number of teams is odd, one team randomly advances and the rest gets paired
            else {
                // Calculate the number of matches played in this round
                int matches = (n - 1) / 2;
                // Update the total number of matches
                totalMatches += matches;
                // Update the number of teams for the next round
                n = (n - 1) / 2 + 1;
            }
        }

        // Return the total number of matches played in the tournament
        return totalMatches;
    }
}

