        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                // Calculate the network rank for the current pair of cities
                int rank = graph.get(i).size() + graph.get(j).size();

                // Subtract 1 if there is a road directly connecting the two cities
                if (graph.get(i).contains(j)) {
                    rank--;
                }

                // Update the maximum network rank
                maxRank = Math.max(maxRank, rank);
            }
        }

        return maxRank;
    }
}

