// #Binary_Search_II_Day_19 #2022_04_22_Time_27_ms_(80.64%)_Space_56.4_MB_(80.28%)
import java.util.Arrays;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        long res = 0;

        for (int i = inventory.length - 1; i >= 0 && orders > 0; i--) {
            if (i == 0 || inventory[i] != inventory[i - 1]) {
                int count = 1;
                while (i - count >= 0 && inventory[i - count] == inventory[i]) {
                    count++;
                }

                // Calculate how many balls can be sold from each group
                long sell = Math.min((long) orders, (long) count * inventory[i]);
                long remainingBalls = inventory[i] - (sell / count);

                if ((sell % count) != 0) {
                    remainingBalls--;
                }

                // Update the orders variable
                orders -= sell;

                // Recalculate the sum using the correct formula
                if (remainingBalls == 0) {
                    res += sum(inventory[i], inventory[i] - (int) ((sell + count - 1) / count)) % MOD * count;
                } else {
                    long total = sum(inventory[i], remainingBalls + 1);
                    for(int j = 0; j < sell % count; j++) {
                        total += inventory[i];
                    }
                    res += (total % MOD) * count;
                }
            } else {
                continue;
            }
        }

        return (int) (res % MOD);
    }

    private long sum(long n, long m) {
        if (n < m) {
            return 0;
        }

        long k = n - m + 1;
        return ((n + m) * k / 2) % MOD;
    }
}

