public class Solution {
    public double findMaxAverage(int[] nums, int k) {
        // Calculate the sum of the first window
        double windowSum = 0;
        for (int i = 0; i < k; i++) {
            windowSum += nums[i];
        }

        // Initialize maxSum with the sum of the first window
        double maxSum = windowSum;

        // Slide the window to the right and update maxSum
        for (int i = k; i < nums.length; i++) {
            // Subtract the leftmost element and add the new element on the right
            windowSum = windowSum - nums[i - k] + nums[i];
            // Update maxSum if the current window sum is larger
            maxSum = Math.max(maxSum, windowSum);
        }

        // Return the maximum average value
        return maxSum / k;
    }
}

