public class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        if (n == 0 || limit < 1) {
            throw new IllegalArgumentException("Invalid input");
        }

        // Initialize count array with size 2 * limit + 2
        int[] count = new int[2 * limit + 2];

        // Iterate over the first half of the array to consider pairs
        for (int i = 0; i < n / 2; i++) {
            int a = Math.min(nums[i], nums[n - 1 - i]);
            int b = Math.max(nums[i], nums[n - 1 - i]);

            // Update count array based on the pair's sum
            count[2]--;
            count[a + 1]++;
            count[a + b]--;
            count[a + b + 1]++;
        }

        // Calculate prefix sums for the count array
        for (int i = 2; i <= 2 * limit; i++) {
            count[i] += count[i - 1];
        }

        // Initialize minMoves with a large value
        int minMoves = Integer.MAX_VALUE;

        // Find the minimum moves by iterating over possible sums
        for (int i = 2; i <= 2 * limit; i++) {
            if (count[i] < minMoves) {
                minMoves = count[i];
            }
        }

        // Ensure the minimum number of moves is not negative and adjust based on array length
        return Math.max(minMoves, 0);
    }
}

