public class Solution {
    public int minStickers(String[] stickers, String target) {
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0);

        for (int mask = 0; mask < (1 << target.length()); mask++) {
            if (!dp.containsKey(mask)) continue;

            for (String sticker : stickers) {
                int newMask = mask;

                for (char ch : sticker.toCharArray()) {
                    int index = target.indexOf(ch, Integer.numberOfTrailingZeros(newMask));

                    while (index != -1 && ((newMask >> index) & 1) == 0) {
                        newMask |= (1 << index);
                        index = target.indexOf(ch, index + 1);
                    }
                }

                if (!dp.containsKey(newMask) || dp.get(mask) + 1 < dp.getOrDefault(newMask, Integer.MAX_VALUE)) {
                    dp.put(newMask, dp.get(mask) + 1);
                }
            }
        }

        return dp.containsKey((1 << target.length()) - 1) ? dp.get((1 << target.length()) - 1) : -1;
    }
}

