// #Hard #Array #Breadth_First_Search #Matrix #Heap_Priority_Queue
// #2022_03_22_Time_417_ms_(73.86%)_Space_118.5_MB_(22.75%)
public class Solution {
    public int cutOffTree(List<List<Integer>> forest) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);

        for (int i = 0; i < forest.size(); i++) {
            for (int j = 0; j < forest.get(0).size(); j++) {
                if (forest.get(i).get(j) > 1) {
                    pq.offer(new int[] {forest.get(i).get(j), i, j});
                }
            }
        }

        int x = 0;
        int y = 0;
        int totalSteps = 0;

        while (!pq.isEmpty()) {
            int[] tree = pq.poll();
            int steps = bfs(forest, x, y, tree[1], tree[2]);
            if (steps == -1) return -1;
            totalSteps += steps;
            forest.get(tree[1]).set(tree[2], 1);
            x = tree[1];
            y = tree[2];
        }

        return totalSteps;
    }

    private int bfs(List<List<Integer>> forest, int sx, int sy, int tx, int ty) {
        if (sx == tx && sy == ty) return 0;

        Queue<int[]> queue = new LinkedList<>();
        boolean[][] visited = new boolean[forest.size()][forest.get(0).size()];

        queue.offer(new int[] {sx, sy});
        visited[sx][sy] = true;
        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] current = queue.poll();
                if (current[0] == tx && current[1] == ty) return steps + 1;

                int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
                for (int[] direction : directions) {
                    int nx = current[0] + direction[0];
                    int ny = current[1] + direction[1];

                    if (nx >= 0 && nx < forest.size() && ny >= 0 && ny < forest.get(0).size()
                        && !visited[nx][ny] && forest.get(nx).get(ny) != 0) {
                        queue.offer(new int[] {nx, ny});
                        visited[nx][ny] = true;
                    }
                }
            }
            steps++;
        }

        return -1;
    }
}

