public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numDecodings(String s) {
        if (s == null || s.length() == 0) return 0;

        long[] dp = new long[s.length() + 1];
        dp[0] = 1;

        // Handle the case when the first character is '*'
        dp[1] = s.charAt(0) == '*' ? 9 : (s.charAt(0) != '0' ? 1 : 0);

        for (int i = 2; i <= s.length(); i++) {
            // If the current character is not zero, we can decode it separately
            if (s.charAt(i - 1) != '0') {
                dp[i] += dp[i - 1];
                if (s.charAt(i - 1) == '*') {
                    dp[i] = (dp[i] + 9 * dp[i - 1]) % MOD;
                }
            }

            // If the current character and the previous one can be decoded together
            if (i > 1 && isValid(s.substring(i - 2, i))) {
                dp[i] += dp[i - 2];
                if (s.charAt(i - 2) == '*' || s.charAt(i - 1) == '*') {
                    int count = getCount(s.substring(i - 2, i));
                    dp[i] = (dp[i] + count * dp[i - 2]) % MOD;
                }
            }

            // Handle overflow
            dp[i] %= MOD;
        }

        return (int) dp[s.length()];
    }

    private boolean isValid(String s) {
        if (s.charAt(0) == '0') return false;

        // Check for '*'
        if (s.contains("*")) {
            // Handle '*' in the first position
            if (s.charAt(0) == '*') {
                if (s.charAt(1) < '7') return true; // 1x or 2x
                else return false;
            } 
            // Handle '*' in the second position
            else if (s.charAt(1) == '*') {
                if (s.charAt(0) == '1' || s.charAt(0) == '2') return true; // 11-19, 21-26
                else return false;
            } 
            // Handle '**'
            else if (s.equals("**")) {
                return true;
            }
        } else {
            // If no '*' is present, directly parse the string
            int num = Integer.parseInt(s);
            return num >= 10 && num <= 26;
        }

        return false;
    }

    private int getCount(String s) {
        if (s.equals("*")) return 0; 
        else if (s.charAt(0) == '*') {
            if (s.charAt(1) < '7') return 2; // 11-16, 21-26
            else return 1; // 17-19, 27 is invalid
        } else if (s.charAt(1) == '*') {
            if (s.charAt(0) == '1') return 9; // 10-19
            else if (s.charAt(0) == '2') return 6; // 20-26
            else return 0;
        } else if (s.equals("**")) {
            int count = 15; // Count of valid two-digit numbers with '**'
            return count;
        } else return 1;
    }
}

