// #Medium #Array #String #Hash_Table #Trie #2022_03_21_Time_14_ms_(87.12%)_Space_58.8_MB_(59.91%)
public class Solution {
    public String replaceWords(List<String> dictionary, String sentence) {
        // Split the sentence into words
        String[] words = sentence.split(" ");

        // Create a Trie data structure to store the roots
        Trie trie = new Trie();
        for (String root : dictionary) {
            trie.insert(root);
        }

        // Replace each word in the sentence with its corresponding root if possible
        for (int i = 0; i < words.length; i++) {
            String root = trie.searchRoot(words[i]);
            if (root != null) {
                words[i] = root;
            }
        }

        // Join the modified words back into a sentence
        return String.join(" ", words);
    }

    private static class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        boolean isEndOfWord;

        public TrieNode() {}
    }

    private static class Trie {
        private final TrieNode root;

        public Trie() {
            this.root = new TrieNode();
        }

        public void insert(String word) {
            TrieNode node = root;
            for (char c : word.toCharArray()) {
                if (!node.children.containsKey(c)) {
                    node.children.put(c, new TrieNode());
                }
                node = node.children.get(c);
            }
            node.isEndOfWord = true;
        }

        public String searchRoot(String word) {
            TrieNode node = root;
            StringBuilder rootBuilder = new StringBuilder();
            for (char c : word.toCharArray()) {
                if (!node.children.containsKey(c)) {
                    return null; // No matching root found
                }
                rootBuilder.append(c);
                node = node.children.get(c);
                if (node.isEndOfWord) {
                    return rootBuilder.toString(); // Found a matching root
                }
            }
            return null;
        }
    }
}

