public class Solution {
    public boolean judgePoint24(int[] cards) {
        double[] doubles = new double[cards.length];
        for (int i = 0; i < cards.length; i++) {
            doubles[i] = cards[i];
        }
        return dfs(doubles, 0);
    }

    private boolean dfs(double[] cards, int index) {
        if (index == 3) {
            return Math.abs(cards[0] - 24.0) < 1e-6;
        }
        for (int i = 0; i < cards.length; i++) {
            for (int j = i + 1; j < cards.length; j++) {
                double[] next = new double[cards.length - 1]; // Corrected size calculation
                int k = 0;

                // Perform operations and check results
                double a = cards[i], b = cards[j];
                for (int l = 0; l < cards.length; l++) {
                    if (l != i && l != j) {
                        next[k++] = cards[l];
                    }
                }

                next[next.length - 1] = a + b;
                if (dfs(next, index + 1)) return true;

                next[next.length - 1] = a - b;
                if (dfs(next, index + 1)) return true;

                next[next.length - 1] = b - a;
                if (dfs(next, index + 1)) return true;

                next[next.length - 1] = a * b;
                if (dfs(next, index + 1)) return true;

                if (b != 0) {
                    next[next.length - 1] = a / b;
                    if (dfs(next, index + 1)) return true;
                }

                if (a != 0) {
                    next[next.length - 1] = b / a;
                    if (dfs(next, index + 1)) return true;
                }
            }
        }
        return false;
