public class Solution {
    public int[] fallingSquares(int[][] positions) {
        int n = positions.length;
        int[] ans = new int[n];
        int[] heights = new int[1000]; // Assuming the maximum width is 1000
        int globalMaxHeight = 0;

        for (int i = 0; i < n; i++) {
            int left = positions[i][0];
            int sideLength = positions[i][1];
            int right = left + sideLength;
            int maxHeight = 0;

            for (int j = left; j < right; j++) {
                maxHeight = Math.max(maxHeight, heights[j]);
            }

            for (int j = left; j < right; j++) {
                heights[j] = maxHeight + sideLength;
            }

            // Update the global maximum height only when necessary
            int newMaxHeight = 0;
            for (int j = left; j < right; j++) {
                newMaxHeight = Math.max(newMaxHeight, heights[j]);
            }
            globalMaxHeight = Math.max(globalMaxHeight, newMaxHeight);

            ans[i] = globalMaxHeight;
        }

        return ans;
    }
