public class Solution {
    public int strangePrinter(String s) {
        int n = s.length();
        char[] chars = s.toCharArray();

        // Remove duplicates by only keeping the first occurrence of each character
        StringBuilder sb = new StringBuilder();
        for (char c : chars) {
            if (sb.length() == 0 || sb.charAt(sb.length() - 1) != c) {
                sb.append(c);
            }
        }

        n = sb.length();
        int[][] dp = new int[n + 1][n + 1];

        // Initialize the base case where there is only one character
        for (int i = 0; i <= n; i++) {
            dp[i][i] = 1;
        }

        // Fill up the dp table in a bottom-up manner
        for (int length = 2; length <= n; length++) {
            for (int left = 0; left <= n - length; left++) {
                int right = left + length - 1;
                dp[left][right] = dp[left + 1][right] + 1;

                // Try to find a character that can be printed together
                for (int k = left + 1; k <= right; k++) {
                    if (sb.charAt(left) == sb.charAt(k)) {
                        dp[left][right] = Math.min(dp[left][right], dp[left + 1][k - 1] + dp[k][right]);
                    }
                }
            }
        }

        return dp[0][n - 1];
    }
}

