import java.util.Arrays;

public class Solution {
    public int findLongestChain(int[][] pairs) {
        if (pairs.length == 0) return 0;

        // Sort the pairs based on their end value
        Arrays.sort(pairs, (a, b) -> a[1] - b[1]);

        int count = 1; // Initialize with 1 because we can always select one pair
        int prevEnd = pairs[0][1]; // Store the end of the first selected pair

        for (int i = 1; i < pairs.length; i++) {
            if (pairs[i][0] > prevEnd) { // If current pair's start is greater than previous pair's end
                count++; // Increase the chain length
                prevEnd = pairs[i][1]; // Update the previous end value
            }
        }

        return count;
    }
}

