    public int flipLights(int n, int presses) {
        // If there are no bulbs or we can't press any buttons, 
        // then the status will always be the same.
        if (n == 0 || presses == 0) return 1;

        // If there is only one bulb, then it can either be on or off after pressing buttons.
        if (n == 1) return 2;

        // If there are two bulbs and we press a button, 
        // then the possible statuses will be: 
        // - both on
        // - both off
        // - one on, one off
        if (n == 2) {
            if (presses >= 1) return 3;
            else return 1;
        }

        // If there are more than two bulbs and we press a button, 
        // then the possible statuses will be: 
        // - all on
        // - all off
        // - even on, odd off
        // - even off, odd on
        // - 3k+1 on, others off (for k = 0, 1, 2, ...)
        if (presses >= 3) return 8;

        // If we can press two buttons, 
        // then the possible statuses will be: 
        // - all on
        // - all off
        // - even on, odd off
        // - even off, odd on
        // - 3k+1 on, others off (for k = 0, 1, 2, ...)
        if (presses == 2) return 7;

        // If we can press one button, 
        // then the possible statuses will be: 
        // - all on
        // - all off
        // - even on, odd off
        // - even off, odd on
        // - 3k+1 on, others off (for k = 0, 1, 2, ...)
        if (presses == 1) return 4;

