// #2022_03_22_Time_1_ms_(96.65%)_Space_44.6_MB_(25.00%)
public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];

        // Find the node with two parents
        int[] candidate1 = null, candidate2 = null;
        for (int[] edge : edges) {
            if (parent[edge[1]] == 0) {
                parent[edge[1]] = edge[0];
            } else {
                candidate1 = new int[] {parent[edge[1]], edge[1]};
                candidate2 = new int[] {edge[0], edge[1]};
                break;
            }
        }

        // Initialize the union-find data structure
        UnionFind uf = new UnionFind(n + 1);

        for (int[] edge : edges) {
            if ((candidate1 != null && Arrays.equals(edge, candidate1)) || 
                (candidate2 != null && Arrays.equals(edge, candidate2))) {
                continue;
            }
            if (!uf.union(edge[0], edge[1])) {
                if (candidate1 == null) {
                    return edge;
                } else {
                    return candidate1;
                }
            }
        }

        // If no cycle is found, the redundant connection must be one of the candidates
        return candidate2;
    }

    private class UnionFind {
        int[] parent;

        public UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public boolean union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return false;
            }
            parent[rootX] = rootY;
            return true;
        }
    }
}

