public class Solution {
    public int leastInterval(char[] tasks, int n) {
        Map<Character, Integer> taskCount = new HashMap<>();

        // Count the frequency of each task
        for (char task : tasks) {
            taskCount.put(task, taskCount.getOrDefault(task, 0) + 1);
        }

        // Find the maximum frequency and the number of tasks with this frequency
        int maxFrequency = 0;
        int maxFrequencyTasks = 0;
        for (int count : taskCount.values()) {
            if (count > maxFrequency) {
                maxFrequency = count;
                maxFrequencyTasks = 1;
            } else if (count == maxFrequency) {
                maxFrequencyTasks++;
            }
        }

        // Calculate the least number of units of time
        int leastTime = (maxFrequency - 1) * (n + 1) + maxFrequencyTasks;
        return Math.max(tasks.length, leastTime);
    }
}

