import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int scheduleCourse(int[][] courses) {
        // Sort the courses based on their deadline date.
        Arrays.sort(courses, (a, b) -> a[1] - b[1]);

        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        int totalTime = 0;

        for (int[] course : courses) {
            // If adding this course doesn't exceed the limit.
            if (totalTime + course[0] <= course[1]) {
                pq.offer(course[0]);
                totalTime += course[0];
            } else if (!pq.isEmpty() && pq.peek() > course[0]) {
                // Remove the longest course and add the current one.
                totalTime -= pq.poll();
                pq.offer(course[0]);
                totalTime += course[0];
            }
        }

        return pq.size();
    }
}

