public class Solution {
    /**
     * Searches for a node with the given value in a binary search tree and returns the subtree rooted at that node.
     *
     * @param root The root of the binary search tree.
     * @param val  The value to be searched in the binary search tree.
     * @return The subtree rooted at the node with the given value, or null if no such node exists.
     */
    public TreeNode searchBST(TreeNode root, int val) {
        // Base case: If the tree is empty or we've found the target value, return the current node
        if (root == null || root.val == val) {
            return root;
        }

        // Recursively search in the left subtree if the target value is less than the current node's value
        if (val < root.val) {
            return searchBST(root.left, val);
        } 
        // Otherwise, recursively search in the right subtree
        else {
            return searchBST(root.right, val);
        }
    }
}

