public class Solution {
    public int calPoints(String[] ops) {
        List<Integer> scores = new ArrayList<>();

        for (String op : ops) {
            if (op.equals("+")) {
                // Record a new score that is the sum of the previous two scores.
                int lastScore1 = scores.get(scores.size() - 1);
                int lastScore2 = scores.get(scores.size() - 2);
                scores.add(lastScore1 + lastScore2);
            } else if (op.equals("D")) {
                // Record a new score that is double the previous score.
                int lastScore = scores.get(scores.size() - 1);
                scores.add(2 * lastScore);
            } else if (op.equals("C")) {
                // Invalidate the previous score, removing it from the record.
                scores.remove(scores.size() - 1);
            } else {
                // Record a new score of x.
                scores.add(Integer.parseInt(op));
            }
        }

        int sum = 0;
        for (int score : scores) {
            sum += score;
        }

        return sum;
    }
}

