import java.util.*;

public class Solution {
    public int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        Map<String, Integer> memo = new HashMap<>();
        return dfs(price, special, needs, memo);
    }

    private int dfs(List<Integer> price, List<List<Integer>> special, List<Integer> needs, Map<String, Integer> memo) {
        String key = needs.toString();
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int res = 0;
        for (int i = 0; i < needs.size(); i++) {
            res += price.get(i) * needs.get(i);
        }

        for (List<Integer> spec : special) {
            List<Integer> clone = new ArrayList<>(needs);
            boolean valid = true;
            for (int i = 0; i < needs.size(); i++) {
                int val = spec.get(i);
                if (val > clone.get(i)) {
                    valid = false;
                    break;
                }
                clone.set(i, clone.get(i) - val);
            }

            if (valid) {
                res = Math.min(res, spec.get(needs.size()) + dfs(price, special, clone, memo));
            }
        }

        memo.put(key, res);
        return res;
    }
}

