public class Solution {
    public int maximumSwap(int num) {
        char[] digits = String.valueOf(num).toCharArray();

        // Store the last occurrence of each digit
        int[] lastOccurrence = new int[10];
        for (int i = 0; i < digits.length; i++) {
            lastOccurrence[digits[i] - '0'] = i;
        }

        // Iterate through the digits and swap if a larger digit is found later
        for (int i = 0; i < digits.length; i++) {
            for (int j = 9; j > digits[i] - '0'; j--) {
                if (lastOccurrence[j] > i) {
                    // Swap the current digit with the last occurrence of the larger digit
                    char temp = digits[i];
                    digits[i] = digits[lastOccurrence[j]];
                    digits[lastOccurrence[j]] = temp;
                    return Integer.parseInt(new String(digits));
                }
            }
        }

        // If no swap is needed, return the original number
        return num;
    }
}

