public class Solution {
    public int[][] imageSmoother(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;

        // Create a new 2D array to store the smoothed image
        int[][] smoothedMatrix = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int sum = matrix[i][j];
                int count = 1;

                // Check the surrounding cells
                for (int x = -1; x <= 1; x++) {
                    for (int y = -1; y <= 1; y++) {
                        if ((x == 0 && y == 0) || i + x < 0 || i + x >= m || j + y < 0 || j + y >= n) {
                            continue;
                        }

                        sum += matrix[i + x][j + y];
                        count++;
                    }
                }

                // Calculate the average and round down
                smoothedMatrix[i][j] = sum / count;
            }
        }

        return smoothedMatrix;
    }
}

