public class Solution {
    private int maxPath = 0;

    public int longestUnivaluePath(TreeNode root) {
        dfs(root);
        return maxPath;
    }

    private int dfs(TreeNode node) {
        if (node == null) {
            return 0;
        }

        int left = dfs(node.left);
        int right = dfs(node.right);

        // If the current node's value is equal to its children, update the path length
        int leftPath = (node.left != null && node.val == node.left.val) ? left + 1 : 0;
        int rightPath = (node.right != null && node.val == node.right.val) ? right + 1 : 0;

        // Update maxPath if a longer path is found
        maxPath = Math.max(maxPath, leftPath + rightPath);

        return Math.max(leftPath, rightPath);
    }
}

