public class Solution {
    /**
     * Adds a row of nodes with value val at the given depth in a binary tree.
     *
     * @param root  The root node of the binary tree.
     * @param val   The value to be added as new nodes.
     * @param depth The depth where the new nodes should be inserted.
     * @return The modified binary tree with the added row of nodes.
     */
    public TreeNode addOneRow(TreeNode root, int val, int depth) {
        if (depth == 1) {
            TreeNode newRoot = new TreeNode(val);
            newRoot.left = root;
            return newRoot;
        }

        addRow(root, val, depth - 1);
        return root;
    }

    /**
     * Recursively adds a row of nodes with value val at the given depth in a binary tree.
     *
     * @param node   The current node being processed.
     * @param val    The value to be added as new nodes.
     * @param depth  The remaining depth where the new nodes should be inserted.
     */
    private void addRow(TreeNode node, int val, int depth) {
        if (node == null || depth < 2) {
            return;
        }

        if (depth == 2) {
            TreeNode tempLeft = node.left;
            TreeNode tempRight = node.right;

            node.left = new TreeNode(val);
            node.right = new TreeNode(val);

            node.left.left = tempLeft;
            node.right.right = tempRight;
        } else {
            addRow(node.left, val, depth - 1);
            addRow(node.right, val, depth - 1);
        }
    }
}

