public class Solution {
    public int[] constructArray(int n, int k) {
        int[] result = new int[n];

        // Fill the first n - k positions with sequential numbers
        for (int i = 0; i < n - k; i++) {
            result[i] = i + 1;
        }

        // Determine the pattern for the remaining k numbers
        boolean isIncreasing = true;
        int left = n - k + 1;
        int right = n;

        // Fill the remaining positions in an alternating manner to introduce unique differences
        for (int i = n - k; i < n; i++) {
            if (isIncreasing) {
                result[i] = left++;
            } else {
                result[i] = right--;
            }
            isIncreasing = !isIncreasing;
        }

        return result;
    }
}

