    /**
     * Detects whether a linked list has a cycle.
     *
     * @param head the head of the linked list
     * @return true if there is a cycle, false otherwise
     */
    public boolean hasCycle(ListNode head) {
        // If the list is empty or only contains one node, it cannot have a cycle
        if (head == null || head.next == null) {
            return false;
        }

        ListNode slow = head;  // Initialize slow pointer to the head of the list
        ListNode fast = head.next;  // Initialize fast pointer to the second node

        while (slow != fast) {
            // If the fast pointer reaches the end, there is no cycle
            if (fast == null || fast.next == null) {
                return false;
            }

            slow = slow.next;  // Move slow pointer one step at a time
            fast = fast.next.next;  // Move fast pointer two steps at a time
        }

        // If the loop ends, it means the slow and fast pointers have met, indicating a cycle
        return true;
    }
}

