public class Solution {
    public int maxProfit(int k, int[] prices) {
        int n = prices.length;

        // If the number of transactions is more than or equal to half of the days,
        // we can simply consider every peak and valley in the price array.
        if (k >= n / 2) {
            int maxProfit = 0;
            for (int i = 1; i < n; i++) {
                if (prices[i] > prices[i - 1]) {
                    maxProfit += prices[i] - prices[i - 1];
                }
            }
            return maxProfit;
        }

        // Initialize a 2D array to store the maximum profit for each subproblem.
        int[][] dp = new int[n][k + 1];

        // Iterate over each day and each possible number of transactions.
        for (int i = 1; i < n; i++) {
            for (int j = 1; j <= k; j++) {
                // Initialize the maximum profit to be 0.
                int maxProfit = 0;

                // Iterate over all previous days to find the maximum profit.
                for (int l = 0; l < i; l++) {
                    // Calculate the profit if we sell on the current day and buy on a previous day.
                    int profit = prices[i] - prices[l] + dp[l][j - 1];

                    // Update the maximum profit.
                    maxProfit = Math.max(maxProfit, profit);
                }

                // Update the dp array with the maximum profit.
                dp[i][j] = Math.max(dp[i - 1][j], maxProfit);
            }
        }

        // Return the maximum profit for the last day and k transactions.
        return dp[n - 1][k];
    }
}

