        int i = 1; // Index to track current value in the list

        while (i < values.size() && !queue.isEmpty()) {
            TreeNode currentNode = queue.poll();

            if (values.get(i) != null) {
                currentNode.left = new TreeNode(values.get(i));
                queue.add(currentNode.left);
            }
            i++;

            if (i < values.size() && values.get(i) != null) {
                currentNode.right = new TreeNode(values.get(i));
                queue.add(currentNode.right);
            }
            i++;
        }

        return root;
    }

    public int maxPathSum(TreeNode root) {
        maxGain(root);
        return maxSum;
    }

    private int maxGain(TreeNode node) {
        if (node == null) {
            return 0;
        }

        // to avoid the -ve values in left side we will compare them with 0
        int left = Math.max(maxGain(node.left), 0);
        int right = Math.max(maxGain(node.right), 0);

        // update maxSum if current path sum is greater than maxSum
        maxSum = Math.max(maxSum, node.val + left + right);

        // return the maximum gain of the current node
        return node.val + Math.max(left, right);
    }
}

