        if (root == null) return null;

        Queue<Node> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                Node node = queue.poll();

                // Assign next pointer if not the last node at this level
                if (i < size - 1) {
                    node.next = queue.peek(); 
