public class Solution {
    public int findMin(int[] nums) {
        int left = 0;
        int right = nums.length - 1;

        while (left < right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] > nums[right]) {
                // If the middle element is greater than the last element, 
                // then the minimum must be in the right half.
                left = mid + 1;
            } else {
                // If the middle element is less than or equal to the last element, 
                // then the minimum must be in the left half.
                right = mid;
            }
        }

        return nums[left];
    }
}

