    /**
     * Detects the node where a cycle begins in a linked list.
     *
     * @param head The head of the linked list.
     * @return The node where the cycle begins, or null if there is no cycle.
     */
    public ListNode detectCycle(ListNode head) {
        if (head == null || head.next == null) {
            return null;
        }

        // Phase 1: Detecting the cycle using Floyd's Tortoise and Hare algorithm
        ListNode tortoise = head;
        ListNode hare = head;

        while (hare != null && hare.next != null) {
            tortoise = tortoise.next; // Move one step at a time
            hare = hare.next.next; // Move two steps at a time

            if (tortoise == hare) {
                break;
            }
        }

        if (hare == null || hare.next == null) {
            return null; // No cycle detected
        }

        // Phase 2: Finding the start of the cycle
        tortoise = head;

        while (tortoise != hare) {
            tortoise = tortoise.next;
            hare = hare.next;
        }

        return tortoise;
    }
}

