public class Solution {
    public boolean isPalindrome(String s) {
        int i = 0, j = s.length() - 1;

        while (i < j) {
            // If character at index i is not alphanumeric, increment i.
            if (!Character.isLetterOrDigit(s.charAt(i))) {
                i++;
            } 
            // If character at index j is not alphanumeric, decrement j.
            else if (!Character.isLetterOrDigit(s.charAt(j))) {
                j--;
            } 
            // If characters at indices i and j are different (ignoring case), return false.
            else if (Character.toLowerCase(s.charAt(i)) != Character.toLowerCase(s.charAt(j))) {
                return false;
            } 
            // If characters match, move towards the center of the string.
            else {
                i++;
                j--;
            }
        }

        return true;
    }
}

