import java.util.*;

public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) return new ArrayList<>();

        Map<String, List<String>> graph = new HashMap<>();
        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);

        boolean found = false;
        int level = 1;
        Map<String, Integer> distance = new HashMap<>();
        distance.put(beginWord, 0);
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String current = queue.poll();
                if (current.equals(endWord)) found = true;
                List<String> neighbors = getNeighbors(current, wordSet);
                graph.putIfAbsent(current, new ArrayList<>());
                graph.get(current).addAll(neighbors);
                for (String neighbor : neighbors) {
                    if (!distance.containsKey(neighbor)) {
                        distance.put(neighbor, level + 1);
                        queue.offer(neighbor);
                    }
                }
            }
            level++;
        }

        if (!found) return new ArrayList<>();

        List<List<String>> result = new ArrayList<>();
        dfs(beginWord, endWord, graph, distance.get(endWord), new LinkedList<>(), result);
        return result;
    }

    private void dfs(String current, String target, Map<String, List<String>> graph, int depth, Deque<String> path, List<List<String>> result) {
        path.offerLast(current);
        if (current.equals(target)) {
            result.add(new ArrayList<>(path));
            path.pollLast();
            return;
        }
        for (String neighbor : graph.getOrDefault(current, new ArrayList<>())) {
            if (graph.containsKey(neighbor) && depth - 1 == distance.get(neighbor)) {
                dfs(neighbor, target, graph, depth - 1, path, result);
            }
        }
        path.pollLast();
    }

    private List<String> getNeighbors(String word, Set<String> wordSet) {
        List<String> neighbors = new ArrayList<>();
        char[] chars = word.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            char original = chars[i];
            for (char c = 'a'; c <= 'z'; c++) {
                if (c == original) continue;
                chars[i] = c;
                String neighbor = new String(chars);
                if (wordSet.contains(neighbor)) neighbors.add(neighbor);
            }
            chars[i] = original;
        }
        return neighbors;
    }

    private Map<String, Integer> distance = new HashMap<>();
}

