public class Solution {
    /**
     * Checks whether a given binary tree is symmetric around its center.
     *
     * @param root The root of the binary tree to check for symmetry.
     * @return True if the binary tree is symmetric, false otherwise.
     */
    public boolean isSymmetric(TreeNode root) {
        // If the tree is empty (i.e., root is null), it's considered symmetric
        if (root == null) return true;

        // Call the helper function to check for symmetry between left and right subtrees
        return isMirror(root.left, root.right);
    }

    /**
     * Helper function to recursively check if two trees are mirror images of each other.
     *
     * @param left  The root of the first tree (left subtree).
     * @param right The root of the second tree (right subtree).
     * @return True if the two trees are mirror images, false otherwise.
     */
    private boolean isMirror(TreeNode left, TreeNode right) {
        // If both trees are empty, they're considered mirror images
        if (left == null && right == null) return true;

        // If one tree is empty and the other isn't, or vice versa, they're not mirror images
        if (left == null || right == null) return false;

        // Check if the values at the current nodes are equal and recursively check the left and right subtrees
        return (left.val == right.val)
                && isMirror(left.right, right.left)
                && isMirror(left.left, right.right);
    }
}

