        int decimalIndex = result.length();

        while (remainder != 0 && !map.containsKey(remainder)) {
            map.put(remainder, decimalIndex);
            remainder *= 10;
            result.append(remainder / denom);
            remainder %= denom;
            decimalIndex++;
        }

        if (remainder != 0) {
            int index = map.get(remainder);
            result.insert(index, "(");
            result.append(")");
        }

        return result.toString();
    }
}

