public class Solution {
    public int maxRepOpt1(String text) {
        Map<Character, Integer> countMap = new HashMap<>();
        for (char c : text.toCharArray()) {
            countMap.put(c, countMap.getOrDefault(c, 0) + 1);
        }

        char[] chars = text.toCharArray();
        int n = chars.length;
        int res = 0;

        // case 1: swap one item to the boundary of a consecutive character block
        for (int i = 0; i < n; ) {
            int j = i + 1;
            while (j < n && chars[j] == chars[i]) {
                j++;
            }
            res = Math.max(res, Math.min(j - i + 1, countMap.get(chars[i])));
            i = j;
        }

        // case 2: find xxxxYxxxxx pattern
        for (int i = 0; i < n; i++) {
            for (int j = i + 2; j <= n; j += 2) {
                char[] temp = chars.clone();
                swap(temp, i, j - 1);
                int maxLen = getMaxLen(temp);
                res = Math.max(res, maxLen);
            }
        }

        return res;
    }

    private void swap(char[] chars, int i, int j) {
        if (i < 0 || j >= chars.length || i == j) {
            return;
        }
        char temp = chars[i];
        chars[i] = chars[j];
        chars[j] = temp;
    }

    private int getMaxLen(char[] chars) {
        Map<Character, Integer> countMap = new HashMap<>();
        for (char c : chars) {
            countMap.put(c, countMap.getOrDefault(c, 0) + 1);
        }
        int n = chars.length;
