public class Solution {
    public int maximumSum(int[] arr) {
        if (arr.length == 0) return 0;

        // Initialize variables to store the maximum sum with and without deletion
        int maxSumWithoutDeletion = Integer.MIN_VALUE, maxSumWithDeletion = Integer.MIN_VALUE;

        // Calculate the maximum sum for each subarray from left to right
        int[] forward = new int[arr.length];
        int currentSum = arr[0];
        forward[0] = arr[0];
        maxSumWithoutDeletion = Math.max(maxSumWithoutDeletion, arr[0]);
        for (int i = 1; i < arr.length; i++) {
            currentSum = Math.max(arr[i], currentSum + arr[i]);
            forward[i] = currentSum;
            maxSumWithoutDeletion = Math.max(maxSumWithoutDeletion, currentSum);
        }

        // Calculate the maximum sum for each subarray from right to left
        int[] backward = new int[arr.length];
        currentSum = arr[arr.length - 1];
        backward[arr.length - 1] = arr[arr.length - 1];
        maxSumWithoutDeletion = Math.max(maxSumWithoutDeletion, arr[arr.length - 1]);
        for (int i = arr.length - 2; i >= 0; i--) {
            currentSum = Math.max(arr[i], currentSum + arr[i]);
            backward[i] = currentSum;
            maxSumWithoutDeletion = Math.max(maxSumWithoutDeletion, currentSum);
        }

        // Calculate the maximum sum with at most one deletion
        for (int i = 0; i < arr.length; i++) {
            for (int j = i; j < arr.length; j++) {
                int subarraySum = 0;
                int maxDeletionSum = Integer.MIN_VALUE;
                for (int k = i; k <= j; k++) {
                    subarraySum += arr[k];
                }
                maxDeletionSum = Math.max(maxDeletionSum, subarraySum);
                for (int k = i; k <= j; k++) {
                    int tempSum = subarraySum - arr[k];
                    if (tempSum > maxDeletionSum && j - i > 0) {
                        maxDeletionSum = tempSum;
                    }
                }
                maxSumWithDeletion = Math.max(maxSumWithDeletion, maxDeletionSum);
            }
        }

        return Math.max(maxSumWithoutDeletion, maxSumWithDeletion);
    }
}

