        boolean shouldDelete = set.contains(node.val);
        if (isRoot && !shouldDelete) {
            res.add(node);
        }

        node.left = solve(node.left, set, res, shouldDelete);
        node.right = solve(node.right, set, res, shouldDelete);

        return shouldDelete ? null : node;
    }

}

