public class Solution {
    public int movesToMakeZigzag(int[] nums) {
        if (nums.length == 1) return 0;

        int res = Integer.MAX_VALUE;

        for (int i = 0; i < 2; i++) {
            int count = 0;
            for (int j = i; j < nums.length; j += 2) {
                if ((j == 0 || nums[j] <= nums[j - 1]) && (j == nums.length - 1 || nums[j] <= nums[j + 1])) {
                    int maxVal = Integer.MIN_VALUE;
                    if (j > 0) maxVal = Math.max(maxVal, nums[j - 1]);
                    if (j < nums.length - 1) maxVal = Math.max(maxVal, nums[j + 1]);
                    count += maxVal - nums[j] + 1;
                } else if ((j != 0 && nums[j] <= nums[j - 1]) || (j != nums.length - 1 && nums[j] <= nums[j + 1])) {
                    int minVal = Integer.MAX_VALUE;
                    if (j > 0) minVal = Math.min(minVal, nums[j - 1]);
                    if (j < nums.length - 1) minVal = Math.min(minVal, nums[j + 1]);
                    count += Math.max(0, minVal - nums[j] + 1);
                }
            }
            res = Math.min(res, count);
        }

        // Handle edge cases
        if (nums.length == 2 && nums[0] <= nums[1]) {
            return 1;
        } else if (nums.length == 2 && nums[0] > nums[1]) {
            return 0;
        }

        return res;
    }
}

