import java.util.ArrayList;

public class Solution {
    public boolean parseBoolExpr(String expression) {
        Stack<Object> stack = new Stack<>();

        for (char c : expression.toCharArray()) {
            if (c == ',') continue;

            if (c == 't' || c == 'f') {
                stack.push(c == 't');
            } else if (c == '!') {
                stack.push('!');
            } else if (c == '&') {
                stack.push('&');
            } else if (c == '|') {
                stack.push('|');
            } else if (c == '(') {
                stack.push('(');
            } else if (c == ')') {
                List<Boolean> list = new ArrayList<>();
                while (!stack.isEmpty() && !stack.peek().equals('(')) {
                    Object obj = stack.pop();
                    if (obj instanceof Boolean) {
                        list.add((Boolean) obj);
                    }
                }
                // Remove the '('
                stack.pop();

                char operator = '\0';
                if (!stack.isEmpty()) {
                    operator = (char) stack.pop();
                }

                boolean result;
                switch (operator) {
                    case '!':
                        result = !list.get(0);
                        break;
                    case '&':
                        result = true;
                        for (boolean b : list) {
                            result &= b;
                        }
                        break;
                    default:
                        result = false;
                        for (boolean b : list) {
                            result |= b;
                        }
                }

                stack.push(result);
            }
        }

        return (Boolean) stack.pop();
    }
}

