public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int kConcatenationMaxSum(int[] arr, int k) {
        long sum = 0;
        for (int num : arr) {
            sum += num;
        }

        if (k == 1) {
            return Math.max(kadane(arr), 0);
        } else if (sum < 0) {
            // If the total sum is negative, directly apply Kadane's algorithm
            int[] temp = new int[arr.length * 2];
            System.arraycopy(arr, 0, temp, 0, arr.length);
            System.arraycopy(arr, 0, temp, arr.length, arr.length);
            long result = Math.max(kadane(temp), 0);
            if (result == 0) {
                // If the maximum sub-array sum is 0 and k > 2, consider all possible sub-arrays
                for (int i = 1; i <= k; i++) {
                    int[] tempK = new int[arr.length * i];
                    System.arraycopy(arr, 0, tempK, 0, arr.length);
                    for (int j = 1; j < i; j++) {
                        System.arraycopy(arr, 0, tempK, arr.length * j, arr.length);
                    }
                    result = Math.max(result, kadane(tempK));
                }
            }
            return (int)(result % MOD);
        } else {
            // Calculate the maximum sub-array sum for k >= 2 and sum >= 0
            long kadaneSum = kadane(arr);
            if (k == 2) {
                int[] temp = new int[arr.length * 2];
                System.arraycopy(arr, 0, temp, 0, arr.length);
                System.arraycopy(arr, 0, temp, arr.length, arr.length);
                return Math.max(kadane(temp), 0) % MOD;
            } else {
                // For k > 2, calculate the maximum sub-array sum considering (k-2) full repetitions
                long result = kadaneSum + ((long)sum * (k - 2));

                // Consider including parts of the first or last repetition by applying Kadane's algorithm on an array with two full repetitions
                int[] temp = new int[arr.length * 2];
                System.arraycopy(arr, 0, temp, 0, arr.length);
                System.arraycopy(arr, 0, temp, arr.length, arr.length);
                result = Math.max(result, kadane(temp));

                if (result < 0) {
                    result += MOD;
                }
                return (int)(Math.max(result % MOD, 0));
            }
        }
    }

    private int kadane(int[] arr) {
        int maxSoFar = Integer.MIN_VALUE;
        int maxEndingHere = 0;

        for (int num : arr) {
            maxEndingHere = Math.max(num, maxEndingHere + num);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
        }

        return maxSoFar;
    }
}

