public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> result = new LinkedList<>();
        int level = 0;
        while ((1 << level) <= label) {
            level++;
        }
        level--;

        while (level >= 0) {
            if (level % 2 == 0) {
                // odd row, left to right
                result.add(0, label);
            } else {
                // even row, right to left
                int nodesInLevel = 1 << level;
                int maxLabel = (1 << (level + 1)) - 1;
                int minLabel = (1 << level);
                int reversedLabel = maxLabel - label + minLabel;
                result.add(0, reversedLabel);
            }

            // move to parent
            if (label == 1) {
                break;
            } else {
                // Correctly calculate the parent's label considering the zigzag pattern
                int nodesBeforeCurrentLevel = (1 << level) - 1;

                int positionInCurrentLevel;
                if (level % 2 == 0) {
                    // Moving from an odd row to its parent in an even row
                    positionInCurrentLevel = label - nodesBeforeCurrentLevel;
                } else {
                    // Moving from an even row to its parent in an odd row, adjust for reversal
                    int maxLabelInCurrentLevel = (1 << (level + 1)) - 1;
                    int minLabelInCurrentLevel = 1 << level;
                    positionInCurrentLevel = label - minLabelInCurrentLevel; // Corrected calculation
                }

                // Calculate the parent's label
                int parentPosition = (positionInCurrentLevel - 1) / 2; 
                if(level % 2 == 0){
                    label = (1 << (level - 1)) + parentPosition;
                } else {
                    int maxLabelInParentLevel = (1 << level) - 1;
                    int minLabelInParentLevel = (1 << (level - 1));
                    label = maxLabelInParentLevel - parentPosition; // Corrected calculation
                }
            }
            level--;
        }

        return result;
    }
}

