// #2023_06_01_Time_4_ms_(96.63%)_Space_44.3_MB_(10.59%)
public class Solution {
    public int[] shortestAlternatingPaths(int n, int[][] redEdges, int[][] blueEdges) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        // Build the graph
        for (int[] edge : redEdges) {
            graph.get(edge[0]).add(new int[]{edge[1], 0});
        }
        for (int[] edge : blueEdges) {
            graph.get(edge[0]).add(new int[]{edge[1], 1});
        }

        // Initialize the result array
        int[] res = new int[n];
        Arrays.fill(res, -1);

        // BFS from node 0
        Queue<int[]> queue = new LinkedList<>();
        boolean[][] visited = new boolean[n][2]; // node, last edge color

        // Add initial nodes to the queue
        for (int[] neighbor : graph.get(0)) {
            queue.offer(new int[]{neighbor[0], 1, neighbor[1]});
            visited[neighbor[0]][neighbor[1]] = true;
        }

        res[0] = 0; // Distance from node 0 to itself is 0
        queue.offer(new int[]{0, 0, -1}); // Add node 0 with distance 0 and no previous color

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();

            if (curr[2] == -1) { // If this is the first visit to a node
                res[curr[0]] = Math.min(res[curr[0]] == -1 ? Integer.MAX_VALUE : res[curr[0]], curr[1]);
            } else {
                if (res[curr[0]] == -1 || res[curr[0]] > curr[1]) {
                    res[curr[0]] = curr[1];
                }
            }

            for (int[] neighbor : graph.get(curr[0])) {
                int nextColor = 1 - neighbor[1]; // Alternate color
                if (!visited[neighbor[0]][nextColor] && (curr[2] == -1 || curr[2] != neighbor[1])) {
                    visited[neighbor[0]][nextColor] = true;
                    queue.offer(new int[]{neighbor[0], curr[1] + 1, nextColor});
                }
            }
        }

        return res;
    }
}

