public class Solution {
    public int distanceBetweenBusStops(int[] distance, int start, int destination) {
        // Calculate total distance of the bus route
        int totalDistance = 0;
        for (int dist : distance) {
            totalDistance += dist;
        }

        // Ensure start is less than or equal to destination
        if (start > destination) {
            int temp = start;
            start = destination;
            destination = temp;
        }

        // Calculate the distance between start and destination in clockwise direction
        int clockwiseDistance = 0;
        for (int i = start; i < destination; i++) {
            clockwiseDistance += distance[i];
        }

        // Return the minimum of clockwise distance and counterclockwise distance
        return Math.min(clockwiseDistance, totalDistance - clockwiseDistance);
    }
}

