import java.util.HashMap;
import java.util.Map;

public class Solution {
    static class ListNode {
        int val;
        ListNode next;
        ListNode() {}
        ListNode(int val) { this.val = val; }
        ListNode(int val, ListNode next) { this.val = val; this.next = next; }
    }

    public ListNode removeZeroSumSublists(ListNode head) {
        // Create a dummy node to simplify the code
        ListNode dummy = new ListNode(0);
        dummy.next = head;

        // Initialize a hashmap to store the prefix sum and its corresponding node
        Map<Integer, ListNode> prefixSumMap = new HashMap<>();
        prefixSumMap.put(0, dummy);

        int prefixSum = 0;

        while (head != null) {
            // Calculate the current prefix sum
            prefixSum += head.val;

            // If we have seen this prefix sum before, it means we have found a zero sum sublist
            if (prefixSumMap.containsKey(prefixSum)) {
                // Get the node that corresponds to the previous occurrence of this prefix sum
                ListNode prevNode = prefixSumMap.get(prefixSum);

                // Calculate the sum of the nodes between the current node and the previous occurrence of this prefix sum
                int tempSum = prefixSum;
                ListNode tempNode = head.next;

                // Remove all nodes that are part of the zero sum sublist from the hashmap
                while (tempNode != null && tempSum + tempNode.val != prefixSum) {
                    tempSum += tempNode.val;
                    if(prefixSumMap.containsKey(tempSum)) {
                        prefixSumMap.remove(tempSum);
                    }
                    tempNode = tempNode.next;
                }

                // Update the next pointer of the previous node to skip over the zero sum sublist
                prevNode.next = head.next;
            } else {
                // If we haven't seen this prefix sum before, add it to the hashmap
                prefixSumMap.put(prefixSum, head);
            }

            // Move on to the next node
            head = head.next;
        }

        return dummy.next;
    }
}

