public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int minNonZeroProduct(int p) {
        long x = (long) Math.pow(2, p) - 1;
        long y = x / 2;

        // Calculate the minimum non-zero product
        long result = powMod(x - 1, y, MOD);

        return (int) ((result * x) % MOD);
    }

    private long powMod(long base, long exponent, int mod) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exponent >>= 1;
        }
        return result;
    }
}

