// #Hard #Depth_First_Search #Graph #Biconnected_Component
public class Solution {
    public List<List<Integer>> criticalConnections(int n, int[][] connections) {
        // build graph
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] connection : connections) {
            int a = connection[0];
            int b = connection[1];
            graph.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
            graph.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
        }

        // record rank
        int[] rank = new int[n];
        Arrays.fill(rank, -1);

        List<List<Integer>> result = new ArrayList<>();
        dfs(graph, 0, -1, rank, result, connections, 0);

        return result;
    }

    private void dfs(Map<Integer, List<Integer>> graph, int node, int parent, int[] rank, List<List<Integer>> result, int[][] connections, int time) {
        if (rank[node] != -1) {
            return;
        }
        rank[node] = time++;
        for (int nei : graph.get(node)) {
            // skip the parent
            if (nei == parent) {
                continue;
            }

            dfs(graph, nei, node, rank, result, connections, time);
            rank[node] = Math.min(rank[node], rank[nei]);

            // check if connection between node and nei is a critical connection
            for (int[] connection : connections) {
                int a = connection[0];
                int b = connection[1];
                if ((a == node && b == nei) || (b == node && a == nei)) {
                    if (rank[nei] > rank[node]) {
                        result.add(Arrays.asList(a, b));
                    }
                }
            }
        }
    }
}

