import java.util.*;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        Arrays.sort(sums);

        // Find the smallest non-zero subset sum
        int minNonZeroSum = Integer.MAX_VALUE;
        for (int i : sums) {
            if (i != 0 && i < minNonZeroSum) {
                minNonZeroSum = i;
            }
        }

        Map<Integer, Integer> map = new HashMap<>();
        for (int sum : sums) {
            map.put(sum, map.getOrDefault(sum, 0) + 1);
        }

        int[] ans = new int[n];
        ans[0] = minNonZeroSum;

        // Remove the subset sums that contain the smallest non-zero element
        Map<Integer, Integer> newMap = new HashMap<>();
        for (int sum : map.keySet()) {
            if (map.get(sum) > 1 && sum - minNonZeroSum >= 0) {
                newMap.put(sum - minNonZeroSum, newMap.getOrDefault(sum - minNonZeroSum, 0) + 1);
            }
        }

        // Recursively find the remaining elements
        int[] remainingSums = new int[newMap.size()];
        int index = 0;
        for (int sum : newMap.keySet()) {
            remainingSums[index++] = sum;
        }

        if (n > 1) {
            int[] subAns = recoverArray(n - 1, remainingSums);
            System.arraycopy(subAns, 0, ans, 1, n - 1);
        }

        // Validate the solution
        Set<Integer> subsetSums = new HashSet<>();
        for (int i = 0; i < (1 << n); i++) {
            int sum = 0;
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) {
                    sum += ans[j];
                }
            }
            subsetSums.add(sum);
        }

        // Check if the generated subset sums match the input
        Set<Integer> inputSubsetSums = new HashSet<>();
        for (int sum : sums) {
            inputSubsetSums.add(sum);
        }

        if (!subsetSums.equals(inputSubsetSums)) {
            // If not, try to find an alternative solution by negating the smallest non-zero subset sum
            ans[0] = -minNonZeroSum;
            for (int i = 1; i < n; i++) {
                ans[i] = -ans[i];
            }
        }

        return ans;
    }
}

