// #Easy #Array #2022_05_15_Time_1_ms_(92.52%)_Space_42.9_MB_(80.72%)
public class Solution {
    public int[] getConcatenation(int[] nums) {
        int n = nums.length;
        int[] ans = new int[2 * n];

        // Copy the first half of the array
        for (int i = 0; i < n; i++) {
            ans[i] = nums[i];
        }

        // Copy the second half of the array
        for (int i = 0; i < n; i++) {
            ans[n + i] = nums[i];
        }

        return ans;
    }
}

