import java.util.Random;

public class Solution {
    public int[] rearrangeArray(int[] nums) {
        Random rand = new Random();
        for (int i = 0; i < nums.length; i++) {
            // Swap the current element with a random index
            int randomIndex = rand.nextInt(nums.length);
            int temp = nums[i];
            nums[i] = nums[randomIndex];
            nums[randomIndex] = temp;
        }

        for (int i = 1; i < nums.length - 1; i++) {
            // Check if the current element is equal to the average of its neighbors
            while ((nums[i-1] + nums[i+1]) / 2.0 == nums[i]) {
                // If it is, swap the current element with a random index
                int randomIndex = rand.nextInt(nums.length);
                int temp = nums[i];
                nums[i] = nums[randomIndex];
                nums[randomIndex] = temp;
            }
        }

        return nums;
    }
}

