// #Medium #Array #Dynamic_Programming #Bit_Manipulation #Backtracking #Bitmask
// #2022_05_18_Time_2_ms_(95.90%)_Space_42.1_MB_(48.72%)
import java.util.Arrays;

public class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int n = students[0].length;
        int m = students.length;

        // Initialize a 2D array to store the compatibility scores
        int[][] scores = new int[m][m];

        // Calculate the compatibility score for each student-mentor pair
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int score = 0;
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) {
                        score++;
                    }
                }
                scores[i][j] = score;
            }
        }

        // Use the Hungarian algorithm to find the optimal assignment
        return hungarianAlgorithm(scores);
    }

    private int hungarianAlgorithm(int[][] matrix) {
        int n = matrix.length;
        int[] u = new int[n];
        int[] v = new int[n];
        int[] p = new int[n];
        boolean[] way = new boolean[n];

        for (int i = 0; i < n; ++i) {
            Arrays.fill(way, false);
            p[0] = i;
            int j0 = 0;
            while (true) {
                way[j0] = true;
                int i0 = p[j0];
                int delta = Integer.MAX_VALUE;
                int j1 = 0;
                for (int j = 0; j < n; ++j)
                    if (!way[j]) {
                        int cur = matrix[i0][j] - u[i0] - v[j];
                        if (cur < delta) {
                            delta = cur;
                            j1 = j;
                        }
                    }
                for (int j = 0; j < n; ++j)
                    if (way[j]) {
                        u[p[j]] += delta;
                        v[j] -= delta;
                    } else
                        p[j] = i;
                j0 = j1;
                if (!way[j0]) break;
            }
        }

        int result = 0;
        for (int i = 0; i < n; ++i)
            result += matrix[i][p[i]];
        return result;
    }
}
